/* মেধার লড়াই — ৩০ স্তরের গণিত প্রস্তুতি: ৩০০টি প্রশ্ন */
(()=> {
 'use strict';
 const bn=n=>String(n).replace(/\d/g,d=>'০১২৩৪৫৬৭৮৯'[+d]);
 const topics=['শতকরা','লাভ-ক্ষতি ও ছাড়','অনুপাত-সমানুপাত','গড়','সরল ও চক্রবৃদ্ধি সুদ','ঐকিক নিয়ম','সময় ও কাজ','সময়-দূরত্ব','বয়স','বীজগণিত','ল.সা.গু ও গ.সা.গু','জ্যামিতি ও ক্ষেত্রফল','ধারা','মিশ্রণ','পরিমিতি','ছাড় ও মূল্য নির্ণয়'];
 const bands=l=>l<=5?'মৌলিক':l<=10?'প্রাথমিক চাকরি পরীক্ষা':l<=15?'মাঝারি প্রতিযোগিতামূলক':l<=20?'উচ্চ-মাঝারি প্রতিযোগিতামূলক':'বিসিএস ও উচ্চতর নিয়োগ';const PROGRESS_KEY='ml_math_level_progress';const readProgress=()=>{try{return JSON.parse(localStorage.getItem(PROGRESS_KEY)||'{}')}catch(e){return {}}};const saveProgress=(l,v)=>{try{const p=readProgress(),old=p[l]||{attempts:0,best:0};p[l]={attempts:old.attempts+1,best:Math.max(old.best,v),lastScore:v,completedAt:new Date().toISOString()};localStorage.setItem(PROGRESS_KEY,JSON.stringify(p))}catch(e){console.warn('গণিতের অগ্রগতি সংরক্ষণ হয়নি',e)}};
 const make=(level,k)=>{
  const n=level*3+k+5, p=5+(level*3+k*2)%36, x=level+k+4;
  let q,ans,formula,solution,shortcut,topic=topics[(level+k)%topics.length];
  switch((level+k)%16){
   case 0:{const base=100*(level+2),rate=p;ans=base*rate/100;q=bn(base)+' টাকার '+bn(rate)+'% কত?';formula='শতকরা পরিমাণ = মূল সংখ্যা × হার ÷ ১০০';solution=bn(base)+' × '+bn(rate)+' ÷ ১০০ = '+bn(ans)+' টাকা।';shortcut=rate%10===0?'১০% বের করে প্রয়োজনীয় গুণিতক নিন।':'হারকে ভগ্নাংশে লিখে মূল সংখ্যার সঙ্গে গুণ করুন।';break}
   case 1:{const cp=100*(level+3),rate=5+(level*2+k*3)%31;if(level%2===0){ans=cp*(100-rate)/100;q='একটি পণ্যের ক্রয়মূল্য '+bn(cp)+' টাকা। '+bn(rate)+'% ক্ষতিতে বিক্রি করলে বিক্রয়মূল্য কত?';formula='বিক্রয়মূল্য = ক্রয়মূল্য × (১০০ − ক্ষতির হার) ÷ ১০০';solution=bn(cp)+' × '+bn(100-rate)+' ÷ ১০০ = '+bn(ans)+' টাকা।';shortcut='ক্ষতির ক্ষেত্রে ১০০% থেকে ক্ষতির হার বাদ দিয়ে গুণ করুন।'}else{ans=cp*(100+rate)/100;q='একটি পণ্যের ক্রয়মূল্য '+bn(cp)+' টাকা। '+bn(rate)+'% লাভে বিক্রয়মূল্য কত?';formula='বিক্রয়মূল্য = ক্রয়মূল্য × (১০০ + লাভের হার) ÷ ১০০';solution=bn(cp)+' × '+bn(100+rate)+' ÷ ১০০ = '+bn(ans)+' টাকা।';shortcut='১০০% ক্রয়মূল্যের সঙ্গে লাভের হার যোগ করে গুণ করুন।'}break}
   case 2:{const a=level+2,b=level*2+5,total=(a+b)*(level+3);ans=total*b/(a+b);q='দুটি সংখ্যার অনুপাত '+bn(a)+':'+bn(b)+' এবং যোগফল '+bn(total)+'। বড় সংখ্যাটি কত?';formula='বড় সংখ্যা = যোগফল × বড় অনুপাত ÷ অনুপাতের যোগফল';solution='মোট অংশ '+bn(a+b)+'; বড় সংখ্যা = '+bn(total)+' × '+bn(b)+' ÷ '+bn(a+b)+' = '+bn(ans)+'।';shortcut='মোট অংশ দিয়ে যোগফল ভাগ করে বড় অংশ দিয়ে গুণ করুন।';break}
   case 3:{const count=4+(level+k)%7,avg=10+level*2;const total=count*avg;ans=total;q=bn(count)+'টি সংখ্যার গড় '+bn(avg)+'। সংখ্যাগুলোর মোট যোগফল কত?';formula='মোট যোগফল = গড় × পদসংখ্যা';solution=bn(avg)+' × '+bn(count)+' = '+bn(total)+'।';shortcut='গড়কে সংখ্যার পরিমাণ দিয়ে গুণ করলেই যোগফল।';break}
   case 4:{const principal=1000*(level+2),rate=2+(level+k)%9,years=1+Math.floor((level-1)/5);if(level%2===0){ans=principal*Math.pow(1+rate/100,years)-principal;q=bn(principal)+' টাকার '+bn(rate)+'% বার্ষিক চক্রবৃদ্ধি সুদে '+bn(years)+' বছরে সুদ কত?';formula='চক্রবৃদ্ধি সুদ = মূলধন × (১ + হার/১০০)^সময় − মূলধন';solution=bn(principal)+' × (১ + '+bn(rate)+'/১০০)^'+bn(years)+' − '+bn(principal)+' = '+bn(ans.toFixed(2))+' টাকা।';shortcut='প্রথমে (১ + হার/১০০) এর সময়-ঘাত বের করে মূলধন দিয়ে গুণ করুন।'}else{ans=principal*rate*years/100;q=bn(principal)+' টাকার '+bn(rate)+'% বার্ষিক সরল সুদে '+bn(years)+' বছরে সুদ কত?';formula='সরল সুদ = মূলধন × হার × সময় ÷ ১০০';solution=bn(principal)+' × '+bn(rate)+' × '+bn(years)+' ÷ ১০০ = '+bn(ans)+' টাকা।';shortcut='প্রথমে ১ বছরের সুদ বের করে বছরের সংখ্যা দিয়ে গুণ করুন।'}break}
   case 5:{const unit=level+3,qty=level+4;ans=unit*qty;q='একটি পণ্যের দাম '+bn(unit)+' টাকা হলে '+bn(qty)+'টি পণ্যের দাম কত?';ans=unit*qty;formula='প্রয়োজনীয় মূল্য = এককের মূল্য × পরিমাণ';solution='একটির দাম '+bn(unit)+' টাকা; '+bn(unit)+' × '+bn(qty)+' = '+bn(ans)+' টাকা।';shortcut='একটির দাম বের করে সরাসরি প্রয়োজনীয় সংখ্যায় গুণ করুন।';break}
   case 6:{const d1=level+1,d2=level+2;if(level%3===0){const d3=level+4;ans=1/(1/d1+1/d2+1/d3);q='ক, খ ও গ যথাক্রমে '+bn(d1)+', '+bn(d2)+' ও '+bn(d3)+' দিনে কাজটি করতে পারে। একত্রে কত দিনে করবে?';formula='যৌথ সময় = ১ ÷ (১/সময়₁ + ১/সময়₂ + ১/সময়₃)';solution='এক দিনের কাজ = ১/'+bn(d1)+' + ১/'+bn(d2)+' + ১/'+bn(d3)+'; যৌথ সময় = '+bn(ans.toFixed(2))+' দিন।';shortcut='প্রত্যেকের এক দিনের কাজ যোগ করে ১ দিয়ে ভাগ করুন।'}else{ans=d1*d2/(d1+d2);q='ক একটি কাজ '+bn(d1)+' দিনে করতে পারে এবং খ কাজটি '+bn(d2)+' দিনে করতে পারে। তারা একত্রে কাজটি কত দিনে শেষ করবে?';formula='যৌথ সময় = (প্রথম সময় × দ্বিতীয় সময়) ÷ (সময় দুটির যোগফল)';solution='এক দিনের কাজ = ১/'+bn(d1)+' + ১/'+bn(d2)+' = '+bn(d1+d2)+'/'+bn(d1*d2)+'; সময় = '+bn(ans.toFixed(2))+' দিন।';shortcut='দুই কর্মীর দিনের সংখ্যা গুণ করে যোগফল দিয়ে ভাগ করুন।'}break}
   case 7:{if(level%3===0){const boat=12+level,stream=2+level%4,hours=2+Math.floor(level/10);ans=(boat-stream)*hours;q='স্থির পানিতে নৌকার বেগ ঘণ্টায় '+bn(boat)+' কিমি এবং স্রোতের বেগ ঘণ্টায় '+bn(stream)+' কিমি। উজানে '+bn(hours)+' ঘণ্টায় কত দূর যাবে?';formula='উজানের বেগ = নৌকার বেগ − স্রোতের বেগ; দূরত্ব = বেগ × সময়';solution='উজানের বেগ = '+bn(boat)+' − '+bn(stream)+' = '+bn(boat-stream)+' কিমি/ঘণ্টা; দূরত্ব = '+bn(boat-stream)+' × '+bn(hours)+' = '+bn(ans)+' কিমি।';shortcut='উজানে বেগ বিয়োগ, ভাটিতে বেগ যোগ; এরপর সময় দিয়ে গুণ।'}else if(level%3===1){const train=120+level*5,platform=180+level*5,speed=20+level;ans=(train+platform)/speed;q='একটি '+bn(train)+' মিটার দীর্ঘ ট্রেন '+bn(platform)+' মিটার প্ল্যাটফর্ম '+bn(speed)+' মি/সে বেগে অতিক্রম করে। সময় কত?';formula='সময় = (ট্রেনের দৈর্ঘ্য + প্ল্যাটফর্মের দৈর্ঘ্য) ÷ বেগ';solution='সময় = ('+bn(train)+' + '+bn(platform)+') ÷ '+bn(speed)+' = '+bn(ans.toFixed(2))+' সেকেন্ড।';shortcut='প্ল্যাটফর্ম পার হতে ট্রেন ও প্ল্যাটফর্ম—দুই দৈর্ঘ্য যোগ করুন।'}else{const speed=20+level*5,hours=1+Math.floor((level-1)/5);ans=speed*hours;q='ঘণ্টায় '+bn(speed)+' কিমি বেগে '+bn(hours)+' ঘণ্টায় কত দূরত্ব অতিক্রম করবে?';formula='দূরত্ব = বেগ × সময়';solution=bn(speed)+' × '+bn(hours)+' = '+bn(ans)+' কিমি।';shortcut='সময় ঘণ্টায় আছে কি না নিশ্চিত করে বেগের সঙ্গে গুণ করুন।'}break}
   case 8:{const son=10+level*2,factor=2+Math.floor((level-1)/5);ans=son;q='পিতা ও সন্তানের বর্তমান বয়সের যোগফল '+bn(son*(factor+1))+' বছর। পিতার বয়স সন্তানের '+bn(factor)+' গুণ। সন্তানের বয়স কত?';formula='সন্তানের বয়স = মোট বয়স ÷ (গুণিতক + ১)';solution='মোট বয়সের অংশ '+bn(factor+1)+'; সন্তানের বয়স = '+bn(son*(factor+1))+' ÷ '+bn(factor+1)+' = '+bn(ans)+' বছর।';shortcut='মোট বয়সকে অনুপাতের মোট অংশ দিয়ে ভাগ করুন।';break}
   case 9:{const coeff=level+1,constant=level*2+3;ans=constant;q=bn(coeff)+'x + '+bn(constant)+' = '+bn(coeff*constant+constant)+' হলে x কত?';formula='ax+b=c হলে x=(c−b)÷a';solution=bn(coeff)+'x = '+bn(coeff*constant)+'; x = '+bn(coeff*constant)+' ÷ '+bn(coeff)+' = '+bn(ans)+'।';shortcut='ধ্রুবক পদ অন্য পাশে নিয়ে সহগ দিয়ে ভাগ করুন।';break}
   case 10:{const a=12+level,b=18+2*level;const gcd=(u,v)=>v?gcd(v,u%v):u;if(level%3===0){ans=gcd(a,b);q=bn(a)+' ও '+bn(b)+'-এর গ.সা.গু কত?';formula='গ.সা.গু = উভয় সংখ্যাকে নিঃশেষে বিভাজ্য সর্বোচ্চ সংখ্যা';solution='ইউক্লিডীয় পদ্ধতিতে '+bn(a)+' ও '+bn(b)+'-এর গ.সা.গু = '+bn(ans)+'।';shortcut='বড় সংখ্যাকে ছোট সংখ্যা দিয়ে ভাগ করে ভাগশেষের সাহায্যে পুনরাবৃত্তি করুন।'}else if(level%3===1){ans=a*b/gcd(a,b);q=bn(a)+' ও '+bn(b)+'-এর ল.সা.গু কত?';formula='ল.সা.গু = সংখ্যা দুটির গুণফল ÷ গ.সা.গু';solution=bn(a)+' × '+bn(b)+' ÷ '+bn(gcd(a,b))+' = '+bn(ans)+'।';shortcut='প্রথমে গ.সা.গু বের করে সংখ্যা দুটির গুণফলকে তা দিয়ে ভাগ করুন।'}else{let n=20+level*3;const prime=v=>{if(v<2)return false;for(let z=2;z*z<=v;z++)if(v%z===0)return false;return true};while(!prime(n))n++;ans=n;q=bn(n-1)+'-এর পরের ক্ষুদ্রতম মৌলিক সংখ্যা কত?';formula='মৌলিক সংখ্যা ১-এর বড় এবং ১ ও নিজে ছাড়া অন্য কোনো ধনাত্মক গুণনীয়ক নেই';solution=bn(n-1)+'-এর পরের সংখ্যা থেকে পরীক্ষা করলে '+bn(ans)+' মৌলিক; এর ১ ও নিজে ছাড়া ভাজক নেই।';shortcut='√n পর্যন্ত সম্ভাব্য মৌলিক ভাজক দিয়ে পরীক্ষা করলেই যথেষ্ট।'}break}
   case 11:{if(level%3===0){const side=4+level;ans=side*side*side;q='একটি ঘনকের এক বাহু '+bn(side)+' সেমি। আয়তন কত?';formula='ঘনকের আয়তন = বাহু³';solution=bn(side)+' × '+bn(side)+' × '+bn(side)+' = '+bn(ans)+' ঘন সেমি।';shortcut='বাহুর মান তিনবার গুণ করুন।'}else if(level%3===1){const base=8+level*2,height=5+level;ans=base*height/2;q='একটি ত্রিভুজের ভূমি '+bn(base)+' সেমি ও উচ্চতা '+bn(height)+' সেমি। ক্ষেত্রফল কত?';formula='ত্রিভুজের ক্ষেত্রফল = ১/২ × ভূমি × উচ্চতা';solution='১/২ × '+bn(base)+' × '+bn(height)+' = '+bn(ans)+' বর্গ সেমি।';shortcut='ভূমি ও উচ্চতা গুণ করে অর্ধেক নিন।'}else{const length=5+level*2,width=3+level;ans=length*width;q='একটি আয়তক্ষেত্রের দৈর্ঘ্য '+bn(length)+' মিটার ও প্রস্থ '+bn(width)+' মিটার। ক্ষেত্রফল কত?';formula='আয়তক্ষেত্রের ক্ষেত্রফল = দৈর্ঘ্য × প্রস্থ';solution=bn(length)+' × '+bn(width)+' = '+bn(ans)+' বর্গমিটার।';shortcut='দৈর্ঘ্য ও প্রস্থ গুণ করুন; একক হবে বর্গ একক।'}break}
   case 12:{const first=level*2+2,diff=level+1,term=level+4;ans=first+(term-1)*diff;q='একটি সমান্তর ধারার প্রথম পদ '+bn(first)+', সাধারণ অন্তর '+bn(diff)+'।';q='একটি সমান্তর ধারার প্রথম পদ '+bn(first)+', সাধারণ অন্তর '+bn(diff)+'। '+bn(term)+'তম পদ কত?';formula='n-তম পদ = প্রথম পদ + (n−১) × সাধারণ অন্তর';solution=bn(first)+' + ('+bn(term)+'−১) × '+bn(diff)+' = '+bn(ans)+'।';shortcut='শেষ পদ বের করতে প্রথম পদের সঙ্গে অন্তরের (n−১) গুণ যোগ করুন।';break}
   case 13:{const v1=20+level*2,v2=30+level*3,total=v1+v2;ans=(v1*2+v2*3)/5;q=bn(v1)+' লিটার '+bn(v2)+'% ঘনত্বের দ্রবণ এবং '+bn(v2)+' লিটার '+bn(v1)+'% ঘনত্বের দ্রবণ মেশালে গড় ঘনত্ব কত?';ans=(v1*v2+v2*v1)/(v1+v2);formula='মিশ্রণের গড় ঘনত্ব = (পরিমাণ₁×ঘনত্ব₁ + পরিমাণ₂×ঘনত্ব₂) ÷ মোট পরিমাণ';solution='('+bn(v1)+'×'+bn(v2)+' + '+bn(v2)+'×'+bn(v1)+') ÷ '+bn(total)+' = '+bn(ans)+'%।';shortcut='প্রতিটি পরিমাণকে তার ঘনত্ব দিয়ে গুণ করে মোট পরিমাণ দিয়ে ভাগ করুন।';break}
   case 15:{const marked=500+level*100,discount=5+(level%6)*5;ans=marked*(100-discount)/100;q='একটি পণ্যের চিহ্নিত মূল্য '+bn(marked)+' টাকা। '+bn(discount)+'% ছাড় দিলে বিক্রয়মূল্য কত?';formula='ছাড়ের পর মূল্য = চিহ্নিত মূল্য × (১০০ − ছাড়ের হার) ÷ ১০০';solution=bn(marked)+' × '+bn(100-discount)+' ÷ ১০০ = '+bn(ans)+' টাকা।';shortcut='চিহ্নিত মূল্য থেকে ছাড়ের শতাংশ বাদ দিয়ে অবশিষ্ট শতাংশের মূল্য বের করুন।';break}
   default:{const radius=7+level*2;ans=2*22/7*radius;q='বৃত্তের ব্যাসার্ধ '+bn(radius)+' সেমি হলে পরিধি কত? (π=২২/৭)';formula='বৃত্তের পরিধি = ২πr';solution='২ × ২২/৭ × '+bn(radius)+' = '+bn(ans)+' সেমি।';shortcut='ব্যাসার্ধকে ৪৪/৭ দিয়ে গুণ করুন।';break}
  }
  const val=Number(ans.toFixed(2));ans=val;
  const candidates=[val,val+Math.max(1,Math.abs(val)*.1),val-Math.max(1,Math.abs(val)*.1),val+Math.max(2,Math.abs(val)*.2)];
  const opts=[...new Set(candidates.map(v=>Number(v.toFixed(2))))];while(opts.length<4)opts.push(Number((val+opts.length*3.17+1).toFixed(2)));
  const ordered=[val,...opts.filter(v=>v!==val).slice(0,3)].sort((a,b)=>((level*13+k*7+Math.round(a))%11)-((level*13+k*7+Math.round(b))%11));
  const a=ordered.indexOf(val);
  return {id:'math_L'+level+'_Q'+(k+1),c:'গণিত · '+topic,q,o:ordered.map(v=>bn(v)),a,level,d:level<=10?'সহজ':level<=20?'মাঝারি':'কঠিন',topic,e:solution,formula,shortcut,expected:val};
 };

 const bank=Array.from({length:30},(_,i)=>Array.from({length:10},(_,k)=>make(i+1,k))).flat();
 // Final consolidation: targeted replacements for invalid premises and arithmetic skill gaps.
 const replaceQuestion=(id,topic,q,options,answer,expected,formula,explanation,shortcut)=>{
  const item=bank.find(x=>x.id===id);if(!item)throw new Error('Missing math question '+id);
  item.c='গণিত · '+topic;item.topic=topic;item.q=q;item.o=options;item.a=answer;item.expected=expected;
  item.d=item.level<=10?'সহজ':item.level<=20?'মাঝারি':'কঠিন';item.formula=formula;item.e=explanation;item.shortcut=shortcut;
 };

 // Candidate rewrite group 21-30: multi-step applied questions, replacing weak one-step items.
 replaceQuestion('math_L14_Q6','গড়','৭টি পরীক্ষার গড় নম্বর ৬৮। প্রথম ৬টি পরীক্ষার মোট নম্বর ৩৯৬ হলে সপ্তম পরীক্ষায় কত নম্বর পেতে হবে?',['৬৮','৭০','৭২','৭৪'],2,80,'সপ্তম পরীক্ষার নম্বর = ৭ × ৬৮ − ৩৯৬','৭টি পরীক্ষার মোট = ৭ × ৬৮ = ৪৭৬। সপ্তম পরীক্ষার নম্বর = ৪৭৬ − ৩৯৬ = ৮০।','গড়কে মোট পরীক্ষার সংখ্যা দিয়ে গুণ করে জানা নম্বরের যোগফল বাদ দিন।');
 replaceQuestion('math_L14_Q8','ঐকিক নিয়ম','৬টি মেশিন ৫ ঘণ্টায় ৯০০টি যন্ত্রাংশ তৈরি করে। একই হারে ৮টি মেশিন ৭ ঘণ্টায় কতটি যন্ত্রাংশ তৈরি করবে?',['১,৫৬০','১,৬০০','১,৬৮০','১,৭২০'],2,1680,'উৎপাদন = প্রতি মেশিন-ঘণ্টার উৎপাদন × মেশিন × ঘণ্টা','প্রতি মেশিন-ঘণ্টায় উৎপাদন = ৯০০ ÷ (৬ × ৫) = ৩০টি। প্রয়োজনীয় উৎপাদন = ৩০ × ৮ × ৭ = ১,৬৮০টি।','মেশিন ও সময়—দুটিই বাড়লে মোট মেশিন-ঘণ্টার অনুপাতে উৎপাদন বাড়ে।');
 replaceQuestion('math_L14_Q10','সময়-দূরত্ব','একটি বাস প্রথম ২ ঘণ্টা ঘণ্টায় ৬০ কিমি এবং পরের ৩ ঘণ্টা ঘণ্টায় ৭২ কিমি বেগে চলে। পুরো যাত্রায় গড় বেগ কত?',['৬৬.০','৬৭.২','৬৮.০','৬৯.৬'],1,67.2,'গড় বেগ = মোট দূরত্ব ÷ মোট সময়','মোট দূরত্ব = ৬০ × ২ + ৭২ × ৩ = ৩৩৬ কিমি। মোট সময় = ৫ ঘণ্টা। গড় বেগ = ৩৩৬ ÷ ৫ = ৬৭.২ কিমি/ঘণ্টা।','বিভিন্ন বেগে চললে বেগগুলোর সাধারণ গড় নয়; মোট দূরত্বকে মোট সময়ে ভাগ করুন।');
 replaceQuestion('math_L15_Q2','শতকরা','একটি পণ্যের দাম ২,৪০০ টাকা। প্রথমে ১৫% বাড়ানো হলো, পরে নতুন দামের ওপর ১০% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?',['২,৩৭৬','২,৪০০','২,৪৮০','২,৫২০'],0,2340,'চূড়ান্ত দাম = ২,৪০০ × ১.১৫ × ০.৯০','বৃদ্ধির পর দাম = ২,৪০০ × ১.১৫ = ২,৭৬০ টাকা। ছাড়ের পর = ২,৭৬০ × ০.৯০ = ২,৪৮৪ টাকা।','প্রতিটি পরিবর্তন আগের ধাপের নতুন দামের ওপর প্রয়োগ করুন।');
 replaceQuestion('math_L15_Q5','গড়','১০ জন কর্মীর গড় বেতন ২৪,০০০ টাকা। ২ জন নতুন কর্মী যোগ দিলে ১২ জনের গড় বেতন ২৫,০০০ টাকা হয়। নতুন দুই কর্মীর মোট বেতন কত?',['৫০,০০০','৫২,০০০','৫৪,০০০','৫৬,০০০'],2,54000,'নতুন কর্মীদের মোট বেতন = ১২ জনের মোট − পুরোনো ১০ জনের মোট','পুরোনো মোট = ১০ × ২৪,০০০ = ২,৪০,০০০ টাকা। নতুন মোট = ১২ × ২৫,০০০ = ৩,০০,০০০ টাকা। নতুন দুইজনের মোট = ৬০,০০০ টাকা।','দুই অবস্থার মোট বেতন বের করে পার্থক্য নিন।');
 replaceQuestion('math_L15_Q7','ঐকিক নিয়ম','১২ জন শ্রমিক প্রতিদিন ৮ ঘণ্টা কাজ করে ১৫ দিনে একটি কাজ শেষ করেন। একই দক্ষতার ২০ জন শ্রমিক প্রতিদিন ৬ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ করবেন?',['১০','১১','১২','১৩'],2,12,'শ্রমিক × দৈনিক ঘণ্টা × দিন = নির্দিষ্ট কাজ','কাজ = ১২ × ৮ × ১৫ = ১,৪৪০ শ্রমিক-ঘণ্টা। নতুন সময় = ১,৪৪০ ÷ (২০ × ৬) = ১২ দিন।','মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন শ্রমিক ও দৈনিক কর্মঘণ্টা দিয়ে ভাগ করুন।');
 replaceQuestion('math_L15_Q9','নৌকা ও স্রোত','একটি নৌকা স্রোতের অনুকূলে ৩০ কিমি যেতে ২ ঘণ্টা এবং প্রতিকূলে ১৮ কিমি যেতে ২ ঘণ্টা নেয়। স্থির পানিতে নৌকার বেগ কত?',['১০','১১','১২','১৩'],2,12,'স্থির পানির বেগ = (অনুকূল বেগ + প্রতিকূল বেগ) ÷ ২','অনুকূল বেগ = ৩০ ÷ ২ = ১৫ কিমি/ঘণ্টা। প্রতিকূল বেগ = ১৮ ÷ ২ = ৯ কিমি/ঘণ্টা। স্থির পানিতে বেগ = (১৫ + ৯) ÷ ২ = ১২ কিমি/ঘণ্টা।','অনুকূল ও প্রতিকূল বেগের গড় নিলে স্রোতের প্রভাব বাদ যায়।');
 replaceQuestion('math_L15_Q10','বয়স','পিতা ও পুত্রের বর্তমান বয়সের যোগফল ৬০ বছর। ৫ বছর আগে পিতার বয়স পুত্রের বয়সের ৪ গুণ ছিল। পুত্রের বর্তমান বয়স কত?',['১৫','১৬','১৭','১৮'],1,16,'ধরি পুত্রের বর্তমান বয়স x; ৫ বছর আগে পিতার বয়স = ৪(x−৫)','পিতার বর্তমান বয়স = ৬০−x। সমীকরণ: ৬০−x−৫ = ৪(x−৫)। তাই ৫৫−x = ৪x−২০; ৭৫ = ৫x; x = ১৫ বছর।','বর্তমান বয়স থেকে ৫ বছর বাদ দিয়ে অতীতের অনুপাত গঠন করুন।');
 replaceQuestion('math_L16_Q1','শতকরা','একটি প্রতিষ্ঠানে ১,২০০ কর্মীর ৩৫% নারী। পরে আরও ৮০ জন নারী কর্মী যোগ দিলে মোট কর্মীর কত শতাংশ নারী হবে?',['৩৮.৭৫%','৪০%','৪১.২৫%','৪২.৫%'],2,41.25,'নারীর নতুন হার = (পুরোনো নারী + নতুন নারী) ÷ নতুন মোট × ১০০','পুরোনো নারী = ১,২০০ × ৩৫% = ৪২০ জন। নতুন নারী = ৫০০ জন; মোট কর্মী = ১,২৮০ জন। হার = ৫০০ ÷ ১,২৮০ × ১০০ = ৩৯.০৬২৫%।','নারীর সংখ্যা ও মোট কর্মী—দুটিই নতুন করে হিসাব করুন।');
 replaceQuestion('math_L16_Q4','গড়','একটি দলের ৮ জনের গড় বয়স ২৬ বছর। ৩৪ বছর বয়সী একজন সদস্য চলে গিয়ে ২২ বছর বয়সী একজন যোগ দিলে দলের নতুন গড় বয়স কত?',['২৪.৫','২৫','২৫.৫','২৬'],1,24.5,'নতুন গড় = (পুরোনো মোট বয়স − বিদায়ী সদস্যের বয়স + নতুন সদস্যের বয়স) ÷ সদস্যসংখ্যা','পুরোনো মোট বয়স = ৮ × ২৬ = ২০৮। নতুন মোট = ২০৮ − ৩৪ + ২২ = ১৯৬। নতুন গড় = ১৯৬ ÷ ৮ = ২৪.৫ বছর।','একজনের পরিবর্তে আরেকজন এলে সদস্যসংখ্যা অপরিবর্তিত থাকে; শুধু মোট বয়স সংশোধন করুন।');


 // QA corrections for candidate rewrite group 21-30: keyed option and expected value must agree.
 replaceQuestion('math_L14_Q6','গড়','৭টি পরীক্ষার গড় নম্বর ৬৮। প্রথম ৬টি পরীক্ষার মোট নম্বর ৩৯৬ হলে সপ্তম পরীক্ষায় কত নম্বর পেতে হবে?',['৭৮','৮০','৮২','৮৪'],1,80,'সপ্তম পরীক্ষার নম্বর = ৭ × ৬৮ − ৩৯৬','৭টি পরীক্ষার মোট = ৭ × ৬৮ = ৪৭৬। সপ্তম পরীক্ষার নম্বর = ৪৭৬ − ৩৯৬ = ৮০।','গড়কে মোট পরীক্ষার সংখ্যা দিয়ে গুণ করে জানা নম্বরের যোগফল বাদ দিন।');
 replaceQuestion('math_L15_Q2','শতকরা','একটি পণ্যের দাম ২,৪০০ টাকা। প্রথমে ১৫% বাড়ানো হলো, পরে নতুন দামের ওপর ১০% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?',['২,৪০০','২,৪৬০','২,৪৮৪','২,৫২০'],2,2484,'চূড়ান্ত দাম = ২,৪০০ × ১.১৫ × ০.৯০','বৃদ্ধির পর দাম = ২,৪০০ × ১.১৫ = ২,৭৬০ টাকা। ছাড়ের পর = ২,৭৬০ × ০.৯০ = ২,৪৮৪ টাকা।','প্রতিটি পরিবর্তন আগের ধাপের নতুন দামের ওপর প্রয়োগ করুন।');
 replaceQuestion('math_L15_Q5','গড়','১০ জন কর্মীর গড় বেতন ২৪,০০০ টাকা। ২ জন নতুন কর্মী যোগ দিলে ১২ জনের গড় বেতন ২৫,০০০ টাকা হয়। নতুন দুই কর্মীর মোট বেতন কত?',['৫৪,০০০','৫৬,০০০','৫৮,০০০','৬০,০০০'],3,60000,'নতুন কর্মীদের মোট বেতন = ১২ জনের মোট − পুরোনো ১০ জনের মোট','পুরোনো মোট = ১০ × ২৪,০০০ = ২,৪০,০০০ টাকা। নতুন মোট = ১২ × ২৫,০০০ = ৩,০০,০০০ টাকা। নতুন দুইজনের মোট = ৬০,০০০ টাকা।','দুই অবস্থার মোট বেতন বের করে পার্থক্য নিন।');
 replaceQuestion('math_L15_Q10','বয়স','পিতা ও পুত্রের বর্তমান বয়সের যোগফল ৬০ বছর। ৫ বছর আগে পিতার বয়স পুত্রের বয়সের ৪ গুণ ছিল। পুত্রের বর্তমান বয়স কত?',['১৪','১৫','১৬','১৭'],1,15,'ধরি পুত্রের বর্তমান বয়স x; ৫ বছর আগে পিতার বয়স = ৪(x−৫)','পিতার বর্তমান বয়স = ৬০−x। সমীকরণ: ৬০−x−৫ = ৪(x−৫)। তাই ৫৫−x = ৪x−২০; ৭৫ = ৫x; x = ১৫ বছর।','বর্তমান বয়স থেকে ৫ বছর বাদ দিয়ে অতীতের অনুপাত গঠন করুন।');
 replaceQuestion('math_L16_Q1','শতকরা','একটি প্রতিষ্ঠানে ১,২০০ কর্মীর ৩৫% নারী। পরে আরও ৮০ জন নারী কর্মী যোগ দিলে মোট কর্মীর কত শতাংশ নারী হবে?',['৩৮.৫%','৩৯.০৬২৫%','৪০%','৪১.২৫%'],1,39.0625,'নারীর নতুন হার = (পুরোনো নারী + নতুন নারী) ÷ নতুন মোট × ১০০','পুরোনো নারী = ১,২০০ × ৩৫% = ৪২০ জন। নতুন নারী = ৫০০ জন; মোট কর্মী = ১,২৮০ জন। হার = ৫০০ ÷ ১,২৮০ × ১০০ = ৩৯.০৬২৫%।','নারীর সংখ্যা ও মোট কর্মী—দুটিই নতুন করে হিসাব করুন।');
 replaceQuestion('math_L16_Q4','গড়','একটি দলের ৮ জনের গড় বয়স ২৬ বছর। ৩৪ বছর বয়সী একজন সদস্য চলে গিয়ে ২২ বছর বয়সী একজন যোগ দিলে দলের নতুন গড় বয়স কত?',['২৪','২৪.৫','২৫','২৫.৫'],1,24.5,'নতুন গড় = (পুরোনো মোট বয়স − বিদায়ী সদস্যের বয়স + নতুন সদস্যের বয়স) ÷ সদস্যসংখ্যা','পুরোনো মোট বয়স = ৮ × ২৬ = ২০৮। নতুন মোট = ২০৮ − ৩৪ + ২২ = ১৯৬। নতুন গড় = ১৯৬ ÷ ৮ = ২৪.৫ বছর।','একজনের পরিবর্তে আরেকজন এলে সদস্যসংখ্যা অপরিবর্তিত থাকে; শুধু মোট বয়স সংশোধন করুন।');

 replaceQuestion('math_L27_Q1','যোগ','একটি প্রতিষ্ঠানের চারটি শাখার ব্যয় যথাক্রমে ৪৮,৭৬৫ টাকা, ৩৯,৮৭৬ টাকা, ২৭,৯৫৮ টাকা ও ১৮,৪৯৭ টাকা। মোট ব্যয় কত?',
 ['১৩৪,০৯৬','১৩৫,০৯৬','১৩৫,৯০৬','১২৫,০৯৬'],1,135096,
 'মোট = চারটি ব্যয়ের যোগফল','৪৮,৭৬৫ + ৩৯,৮৭৬ + ২৭,৯৫৮ + ১৮,৪৯৭ = ১,৩৫,০৯৬ টাকা।',
 'এককের ঘর থেকে ধারসহ কলাম ধরে যোগ করুন; শেষে মোটটি পুনরায় যোগ করে মিলিয়ে নিন।');
 replaceQuestion('math_L28_Q2','বিয়োগ','একটি প্রকল্পের জন্য বরাদ্দ ৩,৫০,০০০ টাকা। প্রথম ধাপে ১,২৮,৭৫০ টাকা এবং দ্বিতীয় ধাপে ৮৬,৯৭৫ টাকা ব্যয় হলে অবশিষ্ট কত?',
 ['১,৩৪,২৭৫','১,৩৫,২৭৫','১,৩৩,০২৫','১,৪৪,২৭৫'],0,134275,
 'অবশিষ্ট = মোট বরাদ্দ − প্রথম ব্যয় − দ্বিতীয় ব্যয়','৩,৫০,০০০ − ১,২৮,৭৫০ = ২,২১,২৫০; ২,২১,২৫০ − ৮৬,৯৭৫ = ১,৩৪,২৭৫ টাকা।',
 'পরপর বিয়োগ করুন; দ্বিতীয় বিয়োগে ধার নেওয়ার ঘরগুলো আলাদা করে যাচাই করুন।');
 replaceQuestion('math_L29_Q1','গুণ','একটি কারখানায় প্রতিদিন ১,২৫৬টি পণ্য তৈরি হয়। ২৪৮ দিনে মোট কতটি পণ্য তৈরি হবে?',
 ['৩১০,৪৮৮','৩১১,৪৮৮','৩১১,৫৮৮','৩২১,৪৮৮'],1,311488,
 'মোট উৎপাদন = দৈনিক উৎপাদন × দিনের সংখ্যা','১,২৫৬ × ২৪৮ = ১,২৫৬ × (২৫০ − ২) = ৩১৪,০০০ − ২,৫১২ = ৩১১,৪৮৮টি।',
 '২৪৮-কে ২৫০ − ২ ধরে গুণ করলে বড় গুণ সহজ হয়।');
 replaceQuestion('math_L30_Q1','ভাগ','৯,৭২,০০০ টাকা ২৪টি শাখায় সমানভাবে ভাগ করা হলো। প্রতিটি শাখার বরাদ্দ আবার ১৫টি প্রকল্পে সমান ভাগ করলে প্রতি প্রকল্প কত টাকা পাবে?',
 ['২,৬০০','২,৭০০','২,৮০০','২৭,০০০'],1,2700,
 'প্রতি প্রকল্পের বরাদ্দ = মোট অর্থ ÷ (শাখা × প্রকল্প)','৯,৭২,০০০ ÷ ২৪ = ৪০,৫০০; ৪০,৫০০ ÷ ১৫ = ২,৭০০ টাকা।',
 'ধাপে ধাপে ভাগ করুন অথবা ২৪ × ১৫ = ৩৬০ দিয়ে মোট অর্থ ভাগ করুন।');
 replaceQuestion('math_L21_Q4','বয়স','একজন পিতার বর্তমান বয়স তাঁর ছেলের বয়সের ৩ গুণ। ১২ বছর পর পিতার বয়স ছেলের বয়সের ২ গুণ হবে। ছেলের বর্তমান বয়স কত?',
 ['১০','১২','১৪','১৬'],1,12,
 'বর্তমান পিতার বয়স = ৩x; ১২ বছর পর ৩x+১২ = ২(x+১২)','৩x + ১২ = ২x + ২৪; x = ১২ বছর।',
 'বর্তমান বয়সকে x ধরে উভয়ের ভবিষ্যৎ বয়সের সমীকরণ গঠন করুন।');
 replaceQuestion('math_L22_Q3','বয়স','একজন পিতার বয়স তাঁর মেয়ের বয়সের চেয়ে ২৮ বছর বেশি। ৪ বছর পর পিতার বয়স মেয়ের বয়সের দ্বিগুণ হবে। মেয়ের বর্তমান বয়স কত?',
 ['২০','২২','২৪','২৬'],2,24,
 'পিতার বয়স = মেয়ের বয়স + ২৮; ৪ বছর পর পিতার বয়স = মেয়ের দ্বিগুণ','ধরি মেয়ের বয়স x; (x+২৮)+৪ = ২(x+৪); তাই x = ২৪ বছর।',
 'বর্তমান বয়সের পার্থক্য অপরিবর্তিত থাকে—এই তথ্য দিয়ে সমীকরণ করুন।');
 replaceQuestion('math_L23_Q2','বয়স','একজন পিতার বর্তমান বয়স তাঁর ছেলের বয়সের ৪ গুণ। ৮ বছর পর পিতার বয়স ছেলের বয়সের ৩ গুণ হবে। ছেলের বর্তমান বয়স কত?',
 ['১৪','১৬','১৮','২০'],1,16,
 'বর্তমান পিতার বয়স = ৪x; ৮ বছর পর ৪x+৮ = ৩(x+৮)','৪x + ৮ = ৩x + ২৪; x = ১৬ বছর।',
 'ভবিষ্যৎ বয়সের অনুপাত থেকে বর্তমান বয়সের সমীকরণ তৈরি করুন।');
 replaceQuestion('math_L24_Q1','বয়স','একজন মায়ের বর্তমান বয়স তাঁর মেয়ের বয়সের ৩ গুণ। ১০ বছর পর মা ও মেয়ের বয়সের যোগফল ৭৬ বছর হবে। মেয়ের বর্তমান বয়স কত?',
 ['১২','১৩','১৪','১৫'],2,14,
 'বর্তমান মোট বয়স = ৩x+x; ১০ বছর পর মোট = ৪x+২০','৪x + ২০ = ৭৬; ৪x = ৫৬; x = ১৪ বছর।',
 'দুইজনের বয়সে ১০ বছর করে যোগ হবে, তাই মোট বয়স ২০ বছর বাড়বে।');
 replaceQuestion('math_L24_Q6','মিশ্রণ','৪০ লিটার ৩০% ঘনত্বের দ্রবণের সঙ্গে ৬০ লিটার ৫০% ঘনত্বের দ্রবণ মেশানো হলো। মিশ্রণের ঘনত্ব কত?',
 ['৪০%','৪২%','৪৫%','৪৮%'],1,42,
 'মিশ্রণের ঘনত্ব = (পরিমাণ₁×ঘনত্ব₁ + পরিমাণ₂×ঘনত্ব₂) ÷ মোট পরিমাণ',
 '(৪০×৩০ + ৬০×৫০) ÷ ১০০ = ৪২%।',
 'প্রতিটি দ্রবণের বিশুদ্ধ উপাদানের পরিমাণ যোগ করে মোট আয়তন দিয়ে ভাগ করুন।');
 replaceQuestion('math_L25_Q5','মিশ্রণ','৮০ লিটার ২৫% ঘনত্বের দ্রবণের সঙ্গে ১২০ লিটার ৪০% ঘনত্বের দ্রবণ মেশানো হলো। মিশ্রণের ঘনত্ব কত?',
 ['৩২%','৩৪%','৩৬%','৩৮%'],1,34,
 'মিশ্রণের ঘনত্ব = (পরিমাণ₁×ঘনত্ব₁ + পরিমাণ₂×ঘনত্ব₂) ÷ মোট পরিমাণ',
 '(৮০×২৫ + ১২০×৪০) ÷ ২০০ = ৬,৮০০ ÷ ২০০ = ৩৪%।',
 'ওজনযুক্ত গড় ব্যবহার করুন; দুই ঘনত্বের সাধারণ গড় নেবেন না।');
 replaceQuestion('math_L26_Q4','মিশ্রণ','৬০ লিটার ২০% ঘনত্বের দ্রবণের সঙ্গে ৯০ লিটার ৫০% ঘনত্বের দ্রবণ মেশানো হলো। মিশ্রণের ঘনত্ব কত?',
 ['৩৪%','৩৬%','৩৮%','৪০%'],2,38,
 'মিশ্রণের ঘনত্ব = (পরিমাণ₁×ঘনত্ব₁ + পরিমাণ₂×ঘনত্ব₂) ÷ মোট পরিমাণ',
 '(৬০×২০ + ৯০×৫০) ÷ ১৫০ = ৩৮%।',
 'প্রথম ও দ্বিতীয় দ্রবণের পরিমাণ আলাদা ওজন হিসেবে ব্যবহার করুন।');
 replaceQuestion('math_L27_Q3','মিশ্রণ','৭৫ লিটার ৩২% ঘনত্বের দ্রবণের সঙ্গে ১২৫ লিটার ৪৮% ঘনত্বের দ্রবণ মেশানো হলো। মিশ্রণের ঘনত্ব কত?',
 ['৪০%','৪২%','৪৪%','৪৬%'],1,42,
 'মিশ্রণের ঘনত্ব = (পরিমাণ₁×ঘনত্ব₁ + পরিমাণ₂×ঘনত্ব₂) ÷ মোট পরিমাণ',
 '(৭৫×৩২ + ১২৫×৪৮) ÷ ২০০ = ৪২%।',
 'মোট দ্রবণের পরিমাণ ২০০ লিটার; উপাদানের পরিমাণের যোগফলকে ২০০ দিয়ে ভাগ করুন।');


 // Consolidation group 1: first ten reversible candidates rewritten as exam-style, level-appropriate questions.
 replaceQuestion('math_L1_Q5','ঐকিক নিয়ম','৩টি খাতার দাম ৭২ টাকা হলে একই দরে ৫টি খাতার দাম কত?',['১০৮','১২০','১৩২','১৪৪'],1,120,'একটির দাম = মোট দাম ÷ খাতার সংখ্যা; প্রয়োজনীয় দাম = একটির দাম × প্রয়োজনীয় সংখ্যা','একটি খাতার দাম = ৭২ ÷ ৩ = ২৪ টাকা। ৫টি খাতার দাম = ২৪ × ৫ = ১২০ টাকা।','আগে এককের দাম বের করে পরে প্রয়োজনীয় সংখ্যার সঙ্গে গুণ করুন।');
 replaceQuestion('math_L2_Q4','সময় ও কাজ','৩ জন শ্রমিক একটি কাজ ১২ দিনে শেষ করেন। একই দক্ষতার ৪ জন শ্রমিক কাজটি কত দিনে শেষ করবেন?',['৮','৯','১০','১২'],1,9,'শ্রমিক × দিন = নির্দিষ্ট কাজ; নতুন সময় = (পুরোনো শ্রমিক × পুরোনো দিন) ÷ নতুন শ্রমিক','মোট কাজ = ৩ × ১২ = ৩৬ শ্রমিক-দিন। ৪ জনে সময় = ৩৬ ÷ ৪ = ৯ দিন।','শ্রমিক বাড়লে সময় কমে—এটি ব্যস্তানুপাত; শ্রমিক-দিন স্থির রাখুন।');
 replaceQuestion('math_L2_Q6','সময়-দূরত্ব','একটি গাড়ি ঘণ্টায় ৫৪ কিমি বেগে ১ ঘণ্টা ২০ মিনিট চলে। গাড়িটি মোট কত দূরত্ব অতিক্রম করে?',['৬৮','৭২','৭৬','৮০'],1,72,'দূরত্ব = বেগ × সময়; ২০ মিনিট = ১/৩ ঘণ্টা','সময় = ১ + ১/৩ = ৪/৩ ঘণ্টা। দূরত্ব = ৫৪ × ৪/৩ = ৭২ কিমি।','সময় মিনিটে থাকলে আগে ঘণ্টায় রূপান্তর করুন।');
 replaceQuestion('math_L3_Q3','শতকরা ও ছাড়','একটি ব্যাগের চিহ্নিত মূল্য ২,৪০০ টাকা। ১৫% ছাড় দিলে ক্রেতাকে কত টাকা দিতে হবে?',['১,৯৮০','২,০৪০','২,১০০','২,১৬০'],1,2040,'ছাড়ের পর মূল্য = চিহ্নিত মূল্য × (১০০ − ছাড়ের হার) ÷ ১০০','ছাড় = ২,৪০০ × ১৫ ÷ ১০০ = ৩৬০ টাকা। বিক্রয়মূল্য = ২,৪০০ − ৩৬০ = ২,০৪০ টাকা।','ছাড়ের টাকা বের করে মূল দাম থেকে বিয়োগ করুন; অথবা অবশিষ্ট ৮৫% নিন।');
 replaceQuestion('math_L4_Q2','গড়','৫টি সংখ্যার গড় ২৮। প্রথম চারটি সংখ্যার যোগফল ১০৪ হলে পঞ্চম সংখ্যাটি কত?',['৩২','৩৪','৩৬','৩৮'],2,36,'মোট যোগফল = গড় × সংখ্যা; অজানা সংখ্যা = মোট যোগফল − জানা যোগফল','৫টি সংখ্যার মোট যোগফল = ২৮ × ৫ = ১৪০। পঞ্চম সংখ্যা = ১৪০ − ১০৪ = ৩৬।','গড় থেকে মোট যোগফল বের করে জানা অংশ বাদ দিন।');
 replaceQuestion('math_L5_Q1','অনুপাত','দুটি সংখ্যার অনুপাত ৩:৫ এবং তাদের যোগফল ৬৪০। ছোট সংখ্যাটি কত?',['২২০','২৪০','২৬০','২৮০'],1,240,'ছোট সংখ্যা = মোট যোগফল × ছোট অনুপাতের অংশ ÷ অনুপাতের মোট অংশ','মোট অংশ = ৩ + ৫ = ৮। ছোট সংখ্যা = ৬৪০ × ৩ ÷ ৮ = ২৪০।','মোট যোগফলকে অনুপাতের মোট অংশ দিয়ে ভাগ করে এক অংশের মান বের করুন।');
 replaceQuestion('math_L5_Q3','সময়-দূরত্ব','১৫০ মিটার দীর্ঘ একটি ট্রেন একটি খুঁটি ১০ সেকেন্ডে অতিক্রম করে। ট্রেনটির বেগ ঘণ্টায় কত কিলোমিটার?',['৪৮','৫৪','৬০','৬৪'],1,54,'বেগ = দূরত্ব ÷ সময়; কিমি/ঘণ্টা পেতে মি/সে-কে ৩.৬ দিয়ে গুণ','বেগ = ১৫০ ÷ ১০ = ১৫ মি/সে। ঘণ্টায় বেগ = ১৫ × ৩.৬ = ৫৪ কিমি/ঘণ্টা।','খুঁটি অতিক্রমে ট্রেনের নিজের দৈর্ঘ্যই অতিক্রান্ত দূরত্ব।');
 replaceQuestion('math_L7_Q10','ধারাবাহিক ছাড়','২,০০০ টাকা দামের একটি পণ্যে প্রথমে ১০% এবং ছাড়ের পরের দামের ওপর আরও ৫% ছাড় দেওয়া হলো। চূড়ান্ত মূল্য কত?',['১,৬৮০','১,৭১০','১,৭২০','১,৮০০'],1,1710,'চূড়ান্ত মূল্য = মূল মূল্য × (১ − প্রথম ছাড়) × (১ − দ্বিতীয় ছাড়)','প্রথম ছাড়ের পর মূল্য = ২,০০০ × ০.৯০ = ১,৮০০ টাকা। দ্বিতীয় ছাড়ের পর = ১,৮০০ × ০.৯৫ = ১,৭১০ টাকা।','ধারাবাহিক ছাড় সরাসরি ১৫% নয়; দ্বিতীয় ছাড় কমে যাওয়া দামের ওপর হিসাব করুন।');
 replaceQuestion('math_L8_Q9','সরল সুদ','৮,০০০ টাকা বার্ষিক ৭.৫% সরল সুদে ২ বছরের জন্য বিনিয়োগ করা হলো। ২ বছরে সুদের পরিমাণ কত?',['১,১০০','১,২০০','১,৩০০','১,৪০০'],1,1200,'সরল সুদ = মূলধন × সুদের হার × সময় ÷ ১০০','সুদ = ৮,০০০ × ৭.৫ × ২ ÷ ১০০ = ১,২০০ টাকা।','বার্ষিক হারকে সময়ের বছরের সংখ্যার সঙ্গে গুণ করুন।');
 replaceQuestion('math_L9_Q8','শতকরা পরিবর্তন','একটি পণ্যের দাম ১,২০০ টাকা থেকে ১৫% বাড়ানো হলো। পরে নতুন দামের ওপর ১০% ছাড় দেওয়া হলে চূড়ান্ত দাম কত?',['১,২০০','১,২৩০','১,২৪২','১,২৬০'],2,1242,'চূড়ান্ত মূল্য = মূল মূল্য × ১.১৫ × ০.৯০','বৃদ্ধির পর মূল্য = ১,২০০ × ১.১৫ = ১,৩৮০ টাকা। ছাড়ের পর = ১,৩৮০ × ০.৯০ = ১,২৪২ টাকা।','শতকরা বৃদ্ধি ও হ্রাস একই মূল্যের ওপর নয়; প্রতিটি ধাপের পর নতুন ভিত্তি নিন।');


 // Consolidation group 2: next ten reversible candidates rewritten with progressively multi-step reasoning.
 replaceQuestion('math_L10_Q7','লাভ-ক্ষতি','একটি পণ্য ১,২৫০ টাকায় কিনে ১২% লাভে বিক্রি করা হলো। বিক্রয়মূল্য কত?',['১,৩৫০','১,৪০০','১,৪৫০','১,৫০০'],1,1400,'বিক্রয়মূল্য = ক্রয়মূল্য × (১০০ + লাভের হার) ÷ ১০০','বিক্রয়মূল্য = ১,২৫০ × ১১২ ÷ ১০০ = ১,৪০০ টাকা।','লাভের ক্ষেত্রে ক্রয়মূল্যের সঙ্গে লাভের হার যোগ করে শতকরা হিসাব করুন।');
 replaceQuestion('math_L11_Q6','ধারাবাহিক শতকরা পরিবর্তন','একজন কর্মীর মাসিক বেতন ৫,০০০ টাকা। প্রথমে ১২% বাড়ানো হলো, পরে সংশোধিত বেতনের ওপর ১০% কর্তন করা হলো। চূড়ান্ত বেতন কত?',['৪,৯৫০','৫,০০০','৫,০৪০','৫,১০০'],2,5040,'চূড়ান্ত বেতন = প্রাথমিক বেতন × ১.১২ × ০.৯০','বৃদ্ধির পর বেতন = ৫,০০০ × ১.১২ = ৫,৬০০ টাকা। কর্তনের পর = ৫,৬০০ × ০.৯০ = ৫,০৪০ টাকা।','দ্বিতীয় শতকরা পরিবর্তন প্রথম পরিবর্তনের পর পাওয়া নতুন বেতনের ওপর প্রয়োগ করুন।');
 replaceQuestion('math_L11_Q9','গড়','৮ জন শিক্ষার্থীর গড় নম্বর ৬৪। নবম শিক্ষার্থী যোগ দেওয়ার পর ৯ জনের গড় ৬৬ হলো। নবম শিক্ষার্থীর নম্বর কত?',['৭৮','৮০','৮২','৮৪'],2,82,'নতুন শিক্ষার্থীর নম্বর = নতুন মোট − পুরোনো মোট','পুরোনো মোট = ৮ × ৬৪ = ৫১২। নতুন মোট = ৯ × ৬৬ = ৫৯৪। নবমের নম্বর = ৫৯৪ − ৫১২ = ৮২।','দুই অবস্থার মোট নম্বর বের করে পার্থক্য নিন।');
 replaceQuestion('math_L12_Q5','চক্রবৃদ্ধি সুদ','১০,০০০ টাকা বার্ষিক ১০% চক্রবৃদ্ধি সুদে ২ বছরের জন্য জমা রাখা হলো। ২ বছর শেষে মোট সুদ কত?',['২,০০০','২,১০০','২,২০০','২,৪০০'],1,2100,'২ বছরের চক্রবৃদ্ধি সুদ = P[(১+r/১০০)² − ১]','প্রথম বছর শেষে = ১০,০০০ × ১.১০ = ১১,০০০ টাকা। দ্বিতীয় বছর শেষে = ১১,০০০ × ১.১০ = ১২,১০০ টাকা। সুদ = ২,১০০ টাকা।','দ্বিতীয় বছরের সুদ প্রথম বছরের সুদসহ নতুন মূলধনের ওপর হিসাব করুন।');
 replaceQuestion('math_L12_Q8','গড়','১২টি সংখ্যার গড় ৪৫। একটি সংখ্যা ৬৮-এর পরিবর্তে ৪৪ লেখা হলে সঠিক গড় কত হবে?',['৪২','৪৩','৪৪','৪৫'],1,43,'সঠিক গড় = (ভুল মোট − ভুল সংখ্যা + সঠিক সংখ্যা) ÷ মোট সংখ্যা','ভুল মোট = ১২ × ৪৫ = ৫৪০। সঠিক মোট = ৫৪০ − ৬৮ + ৪৪ = ৫১৬। সঠিক গড় = ৫১৬ ÷ ১২ = ৪৩।','ভুল সংখ্যাটি বাদ দিয়ে প্রকৃত সংখ্যাটি যোগ করুন; তারপর নতুন মোটকে ১২ দিয়ে ভাগ করুন।');
 replaceQuestion('math_L12_Q10','ঐকিক নিয়ম','৮টি সমান ক্ষমতার মেশিন ৬ ঘণ্টায় ৯৬০টি পণ্য তৈরি করে। একই হারে ১০টি মেশিন ৮ ঘণ্টায় কতটি পণ্য তৈরি করবে?',['১,৪০০','১,৫০০','১,৬০০','১,৭০০'],2,1600,'উৎপাদন ∝ মেশিনের সংখ্যা × সময়','প্রতি মেশিন-ঘণ্টায় উৎপাদন = ৯৬০ ÷ (৮ × ৬) = ২০টি। ১০ × ৮ × ২০ = ১,৬০০টি।','প্রথমে এক মেশিনের এক ঘণ্টার উৎপাদন বের করে নতুন মেশিন-ঘণ্টায় গুণ করুন।');
 replaceQuestion('math_L13_Q4','ধারাবাহিক শতকরা বৃদ্ধি','একটি শহরের জনসংখ্যা ২৫,০০০। প্রথম বছরে ৮% এবং পরের বছরে নতুন জনসংখ্যার ওপর ৫% বৃদ্ধি পেলে দুই বছর শেষে জনসংখ্যা কত হবে?',['২৭,৮০০','২৮,০০০','২৮,৩৫০','২৮,৫০০'],2,28350,'চূড়ান্ত জনসংখ্যা = প্রাথমিক জনসংখ্যা × ১.০৮ × ১.০৫','প্রথম বছর শেষে = ২৫,০০০ × ১.০৮ = ২৭,০০০। দ্বিতীয় বছর শেষে = ২৭,০০০ × ১.০৫ = ২৮,৩৫০ জন।','পরপর বৃদ্ধির ক্ষেত্রে প্রতিবার আগের বছরের নতুন জনসংখ্যাকে ভিত্তি ধরুন।');
 replaceQuestion('math_L13_Q7','গড়','৬টি সংখ্যার গড় ২৪। একটি সংখ্যা বাদ দিলে অবশিষ্ট ৫টি সংখ্যার গড় ২২ হয়। বাদ দেওয়া সংখ্যাটি কত?',['৩০','৩২','৩৪','৩৬'],2,34,'বাদ দেওয়া সংখ্যা = ৬টি সংখ্যার মোট − অবশিষ্ট ৫টির মোট','৬টির মোট = ৬ × ২৪ = ১৪৪। অবশিষ্ট ৫টির মোট = ৫ × ২২ = ১১০। বাদ দেওয়া সংখ্যা = ১৪৪ − ১১০ = ৩৪।','দুই গড়কে সংশ্লিষ্ট সংখ্যার সঙ্গে গুণ করে মোট বের করুন।');
 replaceQuestion('math_L13_Q9','ঐকিক নিয়ম','৪টি প্রিন্টার ৬ মিনিটে ৭২০ পৃষ্ঠা ছাপে। একই গতিতে ৭টি প্রিন্টার ১০ মিনিটে কত পৃষ্ঠা ছাপবে?',['১,৮০০','১,৯০০','২,০০০','২,১০০'],3,2100,'মোট পৃষ্ঠা ∝ প্রিন্টারের সংখ্যা × সময়','প্রতি প্রিন্টার-মিনিটে পৃষ্ঠা = ৭২০ ÷ (৪ × ৬) = ৩০। ৭ × ১০ × ৩০ = ২,১০০ পৃষ্ঠা।','প্রথমে একক প্রিন্টার-মিনিটের উৎপাদন নির্ণয় করুন।');
 replaceQuestion('math_L14_Q3','ধারাবাহিক শতকরা পরিবর্তন','একটি পণ্যের মূল্য ১,৫০০ টাকা। মূল্যের ওপর ২০% কর যোগ করে করসহ মূল্যের ওপর ৫% ছাড় দিলে ক্রেতার পরিশোধযোগ্য অর্থ কত?',['১,৬৮০','১,৭০০','১,৭১০','১,৭৫০'],2,1710,'পরিশোধযোগ্য = মূল মূল্য × ১.২০ × ০.৯৫','করসহ মূল্য = ১,৫০০ × ১.২০ = ১,৮০০ টাকা। ছাড়ের পর = ১,৮০০ × ০.৯৫ = ১,৭১০ টাকা।','কর যোগের পর যে নতুন মূল্য হয়, ছাড় সেই মূল্যের ওপর প্রয়োগ করুন।');

 replaceQuestion('math_L16_Q6','ঐকিক নিয়ম','৬টি মেশিন ৫ ঘণ্টায় ৯০০টি পণ্য তৈরি করে। একই হারে ৮টি মেশিন ৭ ঘণ্টায় কতটি পণ্য তৈরি করবে?',["১,৫৪০","১,৬৮০","১,৭২০","১,৮০০"],1,1680,
 'উৎপাদন = মেশিন × ঘণ্টা × প্রতি মেশিন-ঘণ্টার উৎপাদন','প্রতি মেশিন-ঘণ্টায় উৎপাদন = ৯০০ ÷ (৬×৫) = ৩০টি। নতুন উৎপাদন = ৮×৭×৩০ = ১,৬৮০টি।','আগে এক মেশিনের এক ঘণ্টার উৎপাদন বের করুন; তারপর নতুন মেশিন-ঘণ্টায় গুণ করুন।');
 replaceQuestion('math_L16_Q9','বয়স','একজন পিতার বর্তমান বয়স তাঁর ছেলের ৪ গুণ। ৫ বছর পর তাঁদের বয়সের যোগফল ৬৫ বছর হবে। ছেলের বর্তমান বয়স কত?',["১০","১১","১২","১৩"],1,11,
 'বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের যোগ করা বয়স; পিতা=৪x, ছেলে=x','৫ বছর পর মোট ৬৫; বর্তমান মোট=৬৫−১০=৫৫। ৫x=৫৫; ছেলের বয়স=১১ বছর।','ভবিষ্যৎ মোট থেকে দুজনের জন্য ৫+৫ বছর বাদ দিন।');
 replaceQuestion('math_L17_Q3','গড়','১০ জনের গড় নম্বর ৫৮। একজনের ৪২ নম্বরের বদলে ৬২ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?',["৫৪","৫৫","৫৬","৫৭"],2,56,
 'সঠিক গড় = (ভুল মোট − ভুলভাবে বেশি লেখা নম্বর + প্রকৃত নম্বর) ÷ শিক্ষার্থীসংখ্যা','ভুল মোট=১০×৫৮=৫৮০। সঠিক মোট=৫৮০−৬২+৪২=৫৬০। সঠিক গড়=৫৬০÷১০=৫৬।','ভুল মোট থেকে অতিরিক্ত ২০ নম্বর বাদ দিয়ে নতুন গড় বের করুন।');
 replaceQuestion('math_L17_Q5','ঐকিক নিয়ম','৫টি পাম্প ৮ ঘণ্টায় একটি জলাধারের ৪০% পানি সরায়। একই হারে ৮টি পাম্প ৬ ঘণ্টায় কত শতাংশ পানি সরাবে?',["৪৫%","৪৮%","৫০%","৫২%"],1,48,
 'কাজ ∝ পাম্পের সংখ্যা × সময়','৫×৮=৪০ পাম্প-ঘণ্টায় ৪০% কাজ; প্রতি পাম্প-ঘণ্টায় ১%। ৮×৬=৪৮ পাম্প-ঘণ্টায় ৪৮%।','প্রথমে প্রতি পাম্প-ঘণ্টার কাজ নির্ণয় করুন।');
 replaceQuestion('math_L17_Q7','সময়-দূরত্ব','একটি গাড়ি প্রথম ১২০ কিমি ৬০ কিমি/ঘণ্টা এবং পরের ১৮০ কিমি ৯০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?',["৭০","৭২","৭৫","৮০"],2,75,
 'গড় বেগ = মোট দূরত্ব ÷ মোট সময়','প্রথম অংশে সময়=১২০÷৬০=২ ঘণ্টা; দ্বিতীয় অংশে=১৮০÷৯০=২ ঘণ্টা। মোট দূরত্ব ৩০০ কিমি, সময় ৪ ঘণ্টা; গড় বেগ=৭৫ কিমি/ঘণ্টা।','দুই বেগের সাধারণ গড় নয়; মোট দূরত্বকে মোট সময় দিয়ে ভাগ করুন।');
 replaceQuestion('math_L17_Q8','বয়স','একজন মায়ের বয়স মেয়ের বয়সের ৩ গুণ। ৮ বছর আগে তাঁদের বয়সের যোগফল ৪৮ বছর ছিল। মেয়ের বর্তমান বয়স কত?',["১৪","১৫","১৬","১৭"],2,16,
 'বর্তমান মোট বয়স = অতীতের মোট + দুজনের জন্য ৮+৮; মা=৩x, মেয়ে=x','বর্তমান মোট=৪৮+১৬=৬৪। ৪x=৬৪; মেয়ের বয়স=১৬ বছর।','অতীতের মোট বয়সে দুজনের জন্য ৮ বছর করে যোগ করুন।');
 replaceQuestion('math_L17_Q10','ল.সা.গু ও গ.সা.গু','দুটি ঘণ্টা যথাক্রমে প্রতি ১৮ ও ২৪ মিনিট পরপর বাজে। একসঙ্গে বাজার পর আবার কত মিনিট পর একসঙ্গে বাজবে?',["৬০ মিনিট","৬৬ মিনিট","৭২ মিনিট","৭৮ মিনিট"],2,72,
 'একসঙ্গে বাজার ব্যবধান = ল.সা.গু(১৮,২৪)','১৮=২×৩², ২৪=২³×৩; ল.সা.গু=২³×৩²=৭২ মিনিট।','পরবর্তী একসঙ্গে বাজার ব্যবধান পেতে সময়গুলোর ল.সা.গু বের করুন।');
 replaceQuestion('math_L18_Q2','গড়','একটি পরীক্ষায় ১২ জনের গড় নম্বর ৬৮। আরও ৩ জন যোগ দিলে ১৫ জনের গড় ৭২ হয়। নতুন ৩ জনের গড় নম্বর কত?',["৮৪","৮৬","৮৮","৯০"],2,88,
 'নতুন দলের গড় = (১৫ জনের মোট − ১২ জনের মোট) ÷ ৩','প্রথম মোট=১২×৬৮=৮১৬; নতুন মোট=১৫×৭২=১,০৮০। নতুন ৩ জনের মোট=২৬৪; গড়=২৬৪÷৩=৮৮।','দুই দলের মোট নম্বরের পার্থক্য দিয়ে নতুন দলের গড় বের করুন।');
 replaceQuestion('math_L18_Q4','ঐকিক নিয়ম','১২ জন শ্রমিক দিনে ৬ ঘণ্টা করে ১৫ দিনে একটি কাজ শেষ করেন। ১৮ জন শ্রমিক দিনে ৫ ঘণ্টা কাজ করলে একই কাজ কত দিনে শেষ হবে?',["১০","১১","১২","১৩"],2,12,
 'শ্রমিক × দৈনিক ঘণ্টা × দিন = নির্দিষ্ট কাজ','মোট কাজ=১২×৬×১৫=১,০৮০ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন=১,০৮০÷(১৮×৫)=১২ দিন।','মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দলের দৈনিক কর্মঘণ্টা দিয়ে ভাগ করুন।');
 replaceQuestion('math_L18_Q7','বয়স','একজন পিতার বর্তমান বয়স ছেলের দ্বিগুণ। ৫ বছর আগে তাঁদের বয়সের যোগফল ৫০ বছর ছিল। ৫ বছর পর ছেলের বয়স কত হবে?',["২৫","২৬","২৭","২৮"],0,25,
 'বর্তমান মোট বয়স = অতীতের মোট + দুজনের জন্য ৫+৫; পিতা=২x, ছেলে=x','বর্তমান মোট=৫০+১০=৬০। ৩x=৬০; ছেলের বর্তমান বয়স=২০ বছর। ৫ বছর পর=২৫ বছর।','অতীতের মোট বয়সে দুজনের জন্য ৫ বছর করে যোগ করুন।');

 replaceQuestion('math_L18_Q9','শতকরা',"একটি যন্ত্রের দাম ১২০০ টাকা। প্রথমে দাম ১২% বাড়ল, পরে বর্ধিত দামে ৫% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["১৩৬৬.১৮","১২৭৬.৮","১১৮৭.৪২","১৪৫৫.৫৬"],1,1276.8,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ১২০০ × ১.১২ = ১৩৪৪.০০০০০০০০০০০০২ টাকা। এরপর ছাড়ের পর দাম = ১৩৪৪.০০০০০০০০০০০০২ × ০.৯৫ = ১২৭৬.৮ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L19_Q1','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ১৮৪৫ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ১৩% বেশি রাখা হলো এবং তালিকামূল্যে ৭% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["১৯৩৮.৯১","২০৭৪.৬৩","১৮০৩.১৯","২২১০.৩৫"],0,1938.91,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ১৮৪৫ × ১.১৩ = ২০৮৪.৮৫। বিক্রয়মূল্য = ২০৮৪.৮৫ × ০.৯২৯৯৯৯৯৯৯৯৯৯৯৯৯৯ = ১৯৩৮.৯১ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L19_Q3','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১৪:২১। মোট সদস্য ২১০ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১৩৫","১১৭","১৪৪","১২৬"],3,126,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৩৫। বড় দল = ২১০ × ২১ ÷ ৩৫ = ১২৬ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L19_Q6','গড়',"একটি দলের ১১ জনের গড় নম্বর ৬০। একজনের ৫৮ নম্বর ভুল করে ৬৬ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["৬৪.৯৮","৫৬.৪৮","৬০.৭৩","৬৯.২৩"],2,60.73,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১১ × ৬০ = ৬৬০। সঠিক মোট = ৬৬০ − ৬৬ + ৫৮ = ৬৬৮। গড় = ৬০.৭২৭২৭২৭২৭২৭২৭৩।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L20_Q2','সময় ও কাজ',"১২ জন শ্রমিক দিনে ৭ ঘণ্টা করে ১৬ দিনে একটি কাজ করেন। ১৫ জন শ্রমিক দিনে ৮ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["১২.২","১১.২","১০.২","১৩.২"],1,11.2,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ১২ × ৭ × ১৬ = ১৩৪৪ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ১৩৪৪ ÷ (১৫ × ৮) = ১১.২ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L20_Q4','সময়-দূরত্ব',"একটি গাড়ি ১২০ কিমি পথ ৪৫ কিমি/ঘণ্টা এবং পরের ১৪০ কিমি পথ ৭০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৫৫.৭১","৫৯.৬১","৫১.৮১","৬৩.৫১"],0,55.71,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ১২০÷৪৫ = ২.৬৬৬৬৬৬৬৬৬৬৬৬৬৬৬৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ১৪০÷৭০ = ২ ঘণ্টা। গড় বেগ = ২৬০÷৪.৬৭ = ৫৫.৭১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L20_Q5','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৩ গুণ। ৫ বছর পর তাঁদের বয়সের যোগফল ১০৬ বছর হবে। ৫ বছর পর ছেলের বয়স কত হবে?",["৩১","২৭","৩৩","২৯"],3,29,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ১০৬ − ১০ = ৯৬। ছেলের বর্তমান বয়স = ২৪; ৫ বছর পর = ২৯ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L20_Q7','বীজগণিত',"একটি সংখ্যার ৫ গুণের সঙ্গে একই সংখ্যার ৮ গুণের দ্বিগুণ যোগ করলে ২৯৪ হয়। সংখ্যাটি কত?",["১৫","১৩","১৪","১৬"],2,14,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৫x + ২×৮x = ২৯৪। তাই (২১)x = ২৯৪; x = ১৪।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L21_Q1','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১২ মিনিট ও ২৬ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["১৬৭","১৫৬","১৪৫","১৭৮"],1,156,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১২ ও ২৬-এর গ.সা.গু = ২। ল.সা.গু = (১২×২৬)÷২ = ১৫৬ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L21_Q3','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ১৮ মিটার ও প্রস্থ ১২ মিটার। উভয় মাত্রা ৭ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["২৫৯","২৭৭","২৪১","২৯৫"],0,259,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ১৮×১২ = ২১৬। নতুন ক্ষেত্রফল = ২৫×১৯ = ৪৭৫। বৃদ্ধি = ২৫৯ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L21_Q5','ধারা',"একটি সমান্তর ধারার প্রথম পদ ৭ এবং সাধারণ অন্তর ৩। প্রথম ১৩টি পদের যোগফল ৩২৫ হলে ১৩তম পদ কত?",["৫৪","৪৬","৫৮","৫০"],3,50,"n-তম পদ = a + (n−1)d","n-তম পদ = ৭ + (১৩−১)×৩ = ৫০।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L21_Q6','সরল সুদ',"একটি সঞ্চয়ে ৭৭৫০ টাকা বার্ষিক ৫% সরল সুদে ৫ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["১০৩৬৫.৬৩","৯০০৯.৩৭","৯৬৮৭.৫","১১০৪৩.৭৬"],2,9687.5,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ৭৭৫০×৫×৫÷১০০ = ১৯৩৭.৫ টাকা। মোট = ৭৭৫০+১৯৩৭.৫ = ৯৬৮৭.৫ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L21_Q7','মিশ্রণ',"২২% ও ৬২% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৪ লিটার ও ৮ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৫২.০৮","৪৮.৬৭","৪৫.২৬","৫৫.৪৯"],1,48.67,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ০.৮৮ + ৪.৯৬ = ৫.৮৪ লিটার। মোট আয়তন = ১২ লিটার। ঘনত্ব = ৪৮.৬৭%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L21_Q8','শতকরা',"একটি যন্ত্রের দাম ১৬৫৫ টাকা। প্রথমে দাম ২৪% বাড়ল, পরে বর্ধিত দামে ১০% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["১৮৪৬.৯৮","১৯৭৬.২৭","১৭১৭.৬৯","২১০৫.৫৬"],0,1846.98,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ১৬৫৫ × ১.২৪ = ২০৫২.২ টাকা। এরপর ছাড়ের পর দাম = ২০৫২.২ × ০.৯ = ১৮৪৬.৯৮ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L21_Q10','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ২৪৩০ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ১৬% বেশি রাখা হলো এবং তালিকামূল্যে ১৩% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["২৬২৪.০৩","২২৮০.৬৯","২৭৯৫.৭","২৪৫২.৩৬"],3,2452.36,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ২৪৩০ × ১.১৬ = ২৮১৮.৭৯৯৯৯৯৯৯৯৯৯৯৭। বিক্রয়মূল্য = ২৮১৮.৭৯৯৯৯৯৯৯৯৯৯৯৭ × ০.৮৭ = ২৪৫২.৩৬ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L22_Q4','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১৮:২৬। মোট সদস্য ১৭৬ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১১১","৯৭","১০৪","১১৮"],2,104,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৪৪। বড় দল = ১৭৬ × ২৬ ÷ ৪৪ = ১০৪ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L22_Q5','গড়',"একটি দলের ৯ জনের গড় নম্বর ৮৬। একজনের ৭৮ নম্বর ভুল করে ৯৪ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["৯৩.৯২","৮৭.৭৮","৮১.৬৪","১০০.০৬"],1,87.78,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ৯ × ৮৬ = ৭৭৪। সঠিক মোট = ৭৭৪ − ৯৪ + ৭৮ = ৭৯০। গড় = ৮৭.৭৭৭৭৭৭৭৭৭৭৭৭৭৭।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L22_Q6','সময় ও কাজ',"১১ জন শ্রমিক দিনে ৮ ঘণ্টা করে ১৭ দিনে একটি কাজ করেন। ১৫ জন শ্রমিক দিনে ৯ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["১১.০৮","১২.০৮","১০.০৮","১৩.০৮"],0,11.08,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ১১ × ৮ × ১৭ = ১৪৯৬ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ১৪৯৬ ÷ (১৫ × ৯) = ১১.০৮ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L22_Q7','সময়-দূরত্ব',"একটি গাড়ি ১৯৮ কিমি পথ ৬০ কিমি/ঘণ্টা এবং পরের ১৯২ কিমি পথ ৮০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৭৩.২১","৬৩.৬৩","৭৮","৬৮.৪২"],3,68.42,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ১৯৮÷৬০ = ৩.৩ ঘণ্টা; দ্বিতীয় অংশের সময় = ১৯২÷৮০ = ২.৪ ঘণ্টা। গড় বেগ = ৩৯০÷৫.৭ = ৬৮.৪২ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L22_Q9','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৪ গুণ। ৮ বছর পর তাঁদের বয়সের যোগফল ১৬৬ বছর হবে। ৮ বছর পর ছেলের বয়স কত হবে?",["৪১","৩৫","৩৮","৪৪"],2,38,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ১৬৬ − ১৬ = ১৫০। ছেলের বর্তমান বয়স = ৩০; ৮ বছর পর = ৩৮ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L22_Q10','বীজগণিত',"একটি সংখ্যার ৩ গুণের সঙ্গে একই সংখ্যার ৫ গুণের দ্বিগুণ যোগ করলে ২০৮ হয়। সংখ্যাটি কত?",["১৭","১৬","১৫","১৮"],1,16,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৩x + ২×৫x = ২০৮। তাই (১৩)x = ২০৮; x = ১৬।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L23_Q1','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১৭ মিনিট ও ২১ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["৩৫৭","৩৮২","৩৩২","৪০৭"],0,357,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১৭ ও ২১-এর গ.সা.গু = ১। ল.সা.গু = (১৭×২১)÷১ = ৩৫৭ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L23_Q3','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ২২ মিটার ও প্রস্থ ১১ মিটার। উভয় মাত্রা ৫ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["২০৩","১৭৭","২১৬","১৯০"],3,190,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ২২×১১ = ২৪২। নতুন ক্ষেত্রফল = ২৭×১৬ = ৪৩২। বৃদ্ধি = ১৯০ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L23_Q4','ধারা',"একটি সমান্তর ধারার প্রথম পদ ১২ এবং সাধারণ অন্তর ৬। প্রথম ১৭টি পদের যোগফল ১০২০ হলে ১৭তম পদ কত?",["১২৮","১১২","১২০","১৩৬"],2,120,"n-তম পদ = a + (n−1)d","n-তম পদ = ১২ + (১৭−১)×৬ = ১২০।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L23_Q5','সরল সুদ',"একটি সঞ্চয়ে ১১০০০ টাকা বার্ষিক ৮% সরল সুদে ২ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["১৩৬৫৩","১২৭৬০","১১৮৬৭","১৪৫৪৬"],1,12760,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ১১০০০×৮×২÷১০০ = ১৭৬০ টাকা। মোট = ১১০০০+১৭৬০ = ১২৭৬০ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L23_Q6','মিশ্রণ',"২৫% ও ৬০% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৫ লিটার ও ৬ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৪৪.০৯","৪৭.১৮","৪১","৫০.২৭"],0,44.09,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ১.২৫ + ৩.৬ = ৪.৮৫ লিটার। মোট আয়তন = ১১ লিটার। ঘনত্ব = ৪৪.০৯%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L23_Q8','শতকরা',"একটি যন্ত্রের দাম ২১১০ টাকা। প্রথমে দাম ২২% বাড়ল, পরে বর্ধিত দামে ১৫% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["২৩৪১.২৩","২০৩৪.৯১","২৪৯৪.৩৯","২১৮৮.০৭"],3,2188.07,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ২১১০ × ১.২২ = ২৫৭৪.২ টাকা। এরপর ছাড়ের পর দাম = ২৫৭৪.২ × ০.৮৫ = ২১৮৮.০৭ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L23_Q9','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ৩০১৫ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ১৯% বেশি রাখা হলো এবং তালিকামূল্যে ৯% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["৩৪৯৩.৪৯","৩০৩৬.৩৯","৩২৬৪.৯৪","৩৭২২.০৪"],2,3264.94,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ৩০১৫ × ১.১৯ = ৩৫৮৭.৮৫। বিক্রয়মূল্য = ৩৫৮৭.৮৫ × ০.৯১ = ৩২৬৪.৯৪ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L23_Q10','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১৩:১৮। মোট সদস্য ২১৭ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১৩৫","১২৬","১১৭","১৪৪"],1,126,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৩১। বড় দল = ২১৭ × ১৮ ÷ ৩১ = ১২৬ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L24_Q2','গড়',"একটি দলের ১২ জনের গড় নম্বর ১১২। একজনের ১০৬ নম্বর ভুল করে ১২২ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১১৩.৩৩","১২১.২৬","১০৫.৪","১২৯.১৯"],0,113.33,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১২ × ১১২ = ১৩৪৪। সঠিক মোট = ১৩৪৪ − ১২২ + ১০৬ = ১৩৬০। গড় = ১১৩.৩৩৩৩৩৩৩৩৩৩৩৩৩৩।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L24_Q3','সময় ও কাজ',"১০ জন শ্রমিক দিনে ৬ ঘণ্টা করে ১২ দিনে একটি কাজ করেন। ১৫ জন শ্রমিক দিনে ৭ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["৭.৮৬","৫.৮৬","৮.৮৬","৬.৮৬"],3,6.86,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ১০ × ৬ × ১২ = ৭২০ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ৭২০ ÷ (১৫ × ৭) = ৬.৮৬ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L24_Q4','সময়-দূরত্ব',"একটি গাড়ি ২৭৬ কিমি পথ ৫০ কিমি/ঘণ্টা এবং পরের ২৪৪ কিমি পথ ৯০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬৭.৫৯","৫৮.৭৫","৬৩.১৭","৭২.০১"],2,63.17,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ২৭৬÷৫০ = ৫.৫২ ঘণ্টা; দ্বিতীয় অংশের সময় = ২৪৪÷৯০ = ২.৭১১১১১১১১১১১১১১২ ঘণ্টা। গড় বেগ = ৫২০÷৮.২৩ = ৬৩.১৭ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L24_Q5','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৫ গুণ। ৬ বছর পর তাঁদের বয়সের যোগফল ১০৮ বছর হবে। ৬ বছর পর ছেলের বয়স কত হবে?",["২৪","২২","২০","২৬"],1,22,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ১০৮ − ১২ = ৯৬। ছেলের বর্তমান বয়স = ১৬; ৬ বছর পর = ২২ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L24_Q7','বীজগণিত',"একটি সংখ্যার ৬ গুণের সঙ্গে একই সংখ্যার ৬ গুণের দ্বিগুণ যোগ করলে ১২৬ হয়। সংখ্যাটি কত?",["৭","৮","৬","৯"],0,7,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৬x + ২×৬x = ১২৬। তাই (১৮)x = ১২৬; x = ৭।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L24_Q8','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১৪ মিনিট ও ২৫ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["৩৭৫","৩২৫","৪০০","৩৫০"],3,350,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১৪ ও ২৫-এর গ.সা.গু = ১। ল.সা.গু = (১৪×২৫)÷১ = ৩৫০ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L24_Q9','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ২৬ মিটার ও প্রস্থ ১০ মিটার। উভয় মাত্রা ৩ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["১২৫","১০৯","১১৭","১৩৩"],2,117,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ২৬×১০ = ২৬০। নতুন ক্ষেত্রফল = ২৯×১৩ = ৩৭৭। বৃদ্ধি = ১১৭ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L24_Q10','ধারা',"একটি সমান্তর ধারার প্রথম পদ ৯ এবং সাধারণ অন্তর ৪। প্রথম ১২টি পদের যোগফল ৩৭২ হলে ১২তম পদ কত?",["৬৬","৬২","৫৮","৭০"],1,62,"n-তম পদ = a + (n−1)d","n-তম পদ = ৯ + (১২−১)×৪ = ৬২।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L25_Q1','সরল সুদ',"একটি সঞ্চয়ে ১৪২৫০ টাকা বার্ষিক ৬% সরল সুদে ৩ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["১৬৮১৫","১৭৯৯২","১৫৬৩৮","১৯১৬৯"],0,16815,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ১৪২৫০×৬×৩÷১০০ = ২৫৬৫ টাকা। মোট = ১৪২৫০+২৫৬৫ = ১৬৮১৫ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L25_Q2','মিশ্রণ',"২৮% ও ৫৮% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৬ লিটার ও ৯ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৪৯","৪৩","৫২","৪৬"],3,46,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ১.৬৮ + ৫.২২ = ৬.৯ লিটার। মোট আয়তন = ১৫ লিটার। ঘনত্ব = ৪৬%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L25_Q3','শতকরা',"একটি যন্ত্রের দাম ২৫৬৫ টাকা। প্রথমে দাম ২০% বাড়ল, পরে বর্ধিত দামে ২০% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["২৬৩৪.৭৭","২২৯০.০৩","২৪৬২.৪","২৮০৭.১৪"],2,2462.4,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ২৫৬৫ × ১.২ = ৩০৭৮ টাকা। এরপর ছাড়ের পর দাম = ৩০৭৮ × ০.৮ = ২৪৬২.৪ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L25_Q4','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ৩৬০০ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ২২% বেশি রাখা হলো এবং তালিকামূল্যে ৫% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["৪৪৬৪.৪৭","৪১৭২.৪","৩৮৮০.৩৩","৪৭৫৬.৫৪"],1,4172.4,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ৩৬০০ × ১.২২ = ৪৩৯২। বিক্রয়মূল্য = ৪৩৯২ × ০.৯৫ = ৪১৭২.৪ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L25_Q6','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১৭:২৩। মোট সদস্য ২০০ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১১৫","১২৩","১০৭","১৩১"],0,115,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৪০। বড় দল = ২০০ × ২৩ ÷ ৪০ = ১১৫ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L25_Q7','গড়',"একটি দলের ১০ জনের গড় নম্বর ১৩৮। একজনের ১৩৪ নম্বর ভুল করে ১৪৪ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১৪৯","১২৯","১৫৯","১৩৯"],3,139,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১০ × ১৩৮ = ১৩৮০। সঠিক মোট = ১৩৮০ − ১৪৪ + ১৩৪ = ১৩৯০। গড় = ১৩৯।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L25_Q8','সময় ও কাজ',"৯ জন শ্রমিক দিনে ৭ ঘণ্টা করে ১৩ দিনে একটি কাজ করেন। ১৫ জন শ্রমিক দিনে ৮ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["৭.৮৩","৫.৮৩","৬.৮৩","৮.৮৩"],2,6.83,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ৯ × ৭ × ১৩ = ৮১৯ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ৮১৯ ÷ (১৫ × ৮) = ৬.৮৩ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L25_Q9','সময়-দূরত্ব',"একটি গাড়ি ৩৫৪ কিমি পথ ৬৫ কিমি/ঘণ্টা এবং পরের ২৯৬ কিমি পথ ৬০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬৭","৬২.৬২","৫৮.২৪","৭১.৩৮"],1,62.62,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ৩৫৪÷৬৫ = ৫.৪৪৬১৫৩৮৪৬১৫৩৮৪৬ ঘণ্টা; দ্বিতীয় অংশের সময় = ২৯৬÷৬০ = ৪.৯৩৩৩৩৩৩৩৩৩৩৩৩৩৪ ঘণ্টা। গড় বেগ = ৬৫০÷১০.৩৮ = ৬২.৬২ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L26_Q1','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৩ গুণ। ৪ বছর পর তাঁদের বয়সের যোগফল ৯৬ বছর হবে। ৪ বছর পর ছেলের বয়স কত হবে?",["২৬","২৮","২৪","৩০"],0,26,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ৯৬ − ৮ = ৮৮। ছেলের বর্তমান বয়স = ২২; ৪ বছর পর = ২৬ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L26_Q2','বীজগণিত',"একটি সংখ্যার ৪ গুণের সঙ্গে একই সংখ্যার ৭ গুণের দ্বিগুণ যোগ করলে ১৬২ হয়। সংখ্যাটি কত?",["১০","৮","১১","৯"],3,9,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৪x + ২×৭x = ১৬২। তাই (১৮)x = ১৬২; x = ৯।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L26_Q3','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১৯ মিনিট ও ২০ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["৪০৭","৩৫৩","৩৮০","৪৩৪"],2,380,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১৯ ও ২০-এর গ.সা.গু = ১। ল.সা.গু = (১৯×২০)÷১ = ৩৮০ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L26_Q5','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ২১ মিটার ও প্রস্থ ১৬ মিটার। উভয় মাত্রা ৬ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["২৭৬","২৫৮","২৪০","২৯৪"],1,258,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ২১×১৬ = ৩৩৬। নতুন ক্ষেত্রফল = ২৭×২২ = ৫৯৪। বৃদ্ধি = ২৫৮ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L26_Q6','ধারা',"একটি সমান্তর ধারার প্রথম পদ ৬ এবং সাধারণ অন্তর ৭। প্রথম ১৬টি পদের যোগফল ৯৩৬ হলে ১৬তম পদ কত?",["১১৭","১২৫","১০৯","১৩৩"],0,117,"n-তম পদ = a + (n−1)d","n-তম পদ = ৬ + (১৬−১)×৭ = ১১৭।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L26_Q7','সরল সুদ',"একটি সঞ্চয়ে ১৭৫০০ টাকা বার্ষিক ৪% সরল সুদে ৪ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["২১৭২১","১৮৮৭৯","২৩১৪২","২০৩০০"],3,20300,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ১৭৫০০×৪×৪÷১০০ = ২৮০০ টাকা। মোট = ১৭৫০০+২৮০০ = ২০৩০০ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L26_Q8','মিশ্রণ',"২১% ও ৫৬% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৭ লিটার ও ৭ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৪১.২","৩৫.৮","৩৮.৫","৪৩.৯"],2,38.5,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ১.৪৭ + ৩.৯২ = ৫.৩৯ লিটার। মোট আয়তন = ১৪ লিটার। ঘনত্ব = ৩৮.৫%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L26_Q10','শতকরা',"একটি যন্ত্রের দাম ৩০২০ টাকা। প্রথমে দাম ১৮% বাড়ল, পরে বর্ধিত দামে ৫% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["৩৬২২.৪","৩৩৮৫.৪২","৩১৪৮.৪৪","৩৮৫৯.৩৮"],1,3385.42,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ৩০২০ × ১.১৮ = ৩৫৬৩.৬ টাকা। এরপর ছাড়ের পর দাম = ৩৫৬৩.৬ × ০.৯৫ = ৩৩৮৫.৪২ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L27_Q2','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ৪১৮৫ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ২৫% বেশি রাখা হলো এবং তালিকামূল্যে ১১% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["৪৬৫৫.৮১","৪৯৮১.৭২","৪৩২৯.৯","৫৩০৭.৬৩"],0,4655.81,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ৪১৮৫ × ১.২৫ = ৫২৩১.২৫। বিক্রয়মূল্য = ৫২৩১.২৫ × ০.৮৯ = ৪৬৫৫.৮১ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L27_Q4','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১২:১৯। মোট সদস্য ২৪৮ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১৬৩","১৪১","১৭৪","১৫২"],3,152,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৩১। বড় দল = ২৪৮ × ১৯ ÷ ৩১ = ১৫২ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L27_Q5','গড়',"একটি দলের ৮ জনের গড় নম্বর ১৬৪। একজনের ১৬২ নম্বর ভুল করে ১৭২ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১৭৬.৮২","১৫৩.৬৮","১৬৫.২৫","১৮৮.৩৯"],2,165.25,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ৮ × ১৬৪ = ১৩১২। সঠিক মোট = ১৩১২ − ১৭২ + ১৬২ = ১৩২২। গড় = ১৬৫.২৫।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L27_Q6','সময় ও কাজ',"৮ জন শ্রমিক দিনে ৮ ঘণ্টা করে ১৪ দিনে একটি কাজ করেন। ১১ জন শ্রমিক দিনে ৯ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["১০.০৫","৯.০৫","৮.০৫","১১.০৫"],1,9.05,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ৮ × ৮ × ১৪ = ৮৯৬ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ৮৯৬ ÷ (১১ × ৯) = ৯.০৫ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L27_Q7','সময়-দূরত্ব',"একটি গাড়ি ৪৩২ কিমি পথ ৫৫ কিমি/ঘণ্টা এবং পরের ৩৪৮ কিমি পথ ৭০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬০.৮১","৬৫.০৭","৫৬.৫৫","৬৯.৩৩"],0,60.81,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ৪৩২÷৫৫ = ৭.৮৫৪৫৪৫৪৫৪৫৪৫৪৫৪৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ৩৪৮÷৭০ = ৪.৯৭১৪২৮৫৭১৪২৮৫৭১৫ ঘণ্টা। গড় বেগ = ৭৮০÷১২.৮৩ = ৬০.৮১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L27_Q9','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৪ গুণ। ৭ বছর পর তাঁদের বয়সের যোগফল ১৫৪ বছর হবে। ৭ বছর পর ছেলের বয়স কত হবে?",["৩৭","৩৩","৩৯","৩৫"],3,35,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ১৫৪ − ১৪ = ১৪০। ছেলের বর্তমান বয়স = ২৮; ৭ বছর পর = ৩৫ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L27_Q10','বীজগণিত',"একটি সংখ্যার ৭ গুণের সঙ্গে একই সংখ্যার ৮ গুণের দ্বিগুণ যোগ করলে ২৫৩ হয়। সংখ্যাটি কত?",["১২","১০","১১","১৩"],2,11,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৭x + ২×৮x = ২৫৩। তাই (২৩)x = ২৫৩; x = ১১।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L28_Q1','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১৬ মিনিট ও ২৪ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["৫১","৪৮","৪৫","৫৪"],1,48,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১৬ ও ২৪-এর গ.সা.গু = ৮। ল.সা.গু = (১৬×২৪)÷৮ = ৪৮ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L28_Q3','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ২৫ মিটার ও প্রস্থ ১৫ মিটার। উভয় মাত্রা ৪ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["১৭৬","১৮৮","১৬৪","২০০"],0,176,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ২৫×১৫ = ৩৭৫। নতুন ক্ষেত্রফল = ২৯×১৯ = ৫৫১। বৃদ্ধি = ১৭৬ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L28_Q4','ধারা',"একটি সমান্তর ধারার প্রথম পদ ১১ এবং সাধারণ অন্তর ৫। প্রথম ২০টি পদের যোগফল ১১৭০ হলে ২০তম পদ কত?",["১২৫","১০৯","১৩৩","১১৭"],3,117,"n-তম পদ = a + (n−1)d","n-তম পদ = ১১ + (২০−১)×৫ = ১১৭।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L28_Q5','সরল সুদ',"একটি সঞ্চয়ে ২০৭৫০ টাকা বার্ষিক ৭% সরল সুদে ৫ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["২৯৯৭৩.৩৮","২৬০৫১.৬২","২৮০১২.৫","৩১৯৩৪.২৬"],2,28012.5,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ২০৭৫০×৭×৫÷১০০ = ৭২৬২.৫ টাকা। মোট = ২০৭৫০+৭২৬২.৫ = ২৮০১২.৫ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L28_Q6','মিশ্রণ',"২৪% ও ৫৪% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৪ লিটার ও ১০ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৪৮.৬১","৪৫.৪৩","৪২.২৫","৫১.৭৯"],1,45.43,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ০.৯৬ + ৫.৪ = ৬.৩৬ লিটার। মোট আয়তন = ১৪ লিটার। ঘনত্ব = ৪৫.৪৩%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L28_Q8','শতকরা',"একটি যন্ত্রের দাম ৩৪৭৫ টাকা। প্রথমে দাম ১৬% বাড়ল, পরে বর্ধিত দামে ১০% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["৩৬২৭.৯","৩৮৮১.৮৫","৩৩৭৩.৯৫","৪১৩৫.৮"],0,3627.9,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ৩৪৭৫ × ১.১৬ = ৪০৩০.৯৯৯৯৯৯৯৯৯৯৯৯৫ টাকা। এরপর ছাড়ের পর দাম = ৪০৩০.৯৯৯৯৯৯৯৯৯৯৯৯৫ × ০.৯ = ৩৬২৭.৯ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");
 replaceQuestion('math_L28_Q10','লাভ-ক্ষতি',"একটি পণ্যের ক্রয়মূল্য ৪৭৭০ টাকা। তালিকামূল্য ক্রয়মূল্যের চেয়ে ১০% বেশি রাখা হলো এবং তালিকামূল্যে ৭% ছাড় দেওয়া হলো। বিক্রয়মূল্য কত?",["৫২২১.২৯","৪৫৩৮.১৩","৫৫৬২.৮৭","৪৮৭৯.৭১"],3,4879.71,"বিক্রয়মূল্য = ক্রয়মূল্য × (১ + লাভের হার) × (১ − ছাড়)","তালিকামূল্য = ৪৭৭০ × ১.১ = ৫২৪৭। বিক্রয়মূল্য = ৫২৪৭ × ০.৯২৯৯৯৯৯৯৯৯৯৯৯৯৯৯ = ৪৮৭৯.৭১ টাকা।","প্রথমে তালিকামূল্য, পরে ছাড়ের অঙ্ক নির্ণয় করুন।");
 replaceQuestion('math_L29_Q2','অনুপাত',"দুটি দলের সদস্যসংখ্যার অনুপাত ১৬:২৪। মোট সদস্য ২৪০ জন হলে বড় দলের সদস্যসংখ্যা কত?",["১৫৪","১৩৪","১৪৪","১৬৪"],2,144,"বড় দলের সদস্য = মোট সদস্য × বড় অনুপাত ÷ অনুপাতের যোগফল","মোট অংশ = ৪০। বড় দল = ২৪০ × ২৪ ÷ ৪০ = ১৪৪ জন।","মোটকে অনুপাতের মোট অংশ দিয়ে ভাগ করে বড় দলের অংশ দিয়ে গুণ করুন।");
 replaceQuestion('math_L29_Q3','গড়',"একটি দলের ১১ জনের গড় নম্বর ১৯০। একজনের ১৮২ নম্বর ভুল করে ২০০ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["২০৫.০৫","১৯১.৬৪","১৭৮.২৩","২১৮.৪৬"],1,191.64,"সঠিক গড় = (ভুল মোট − ভুল নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১১ × ১৯০ = ২০৯০। সঠিক মোট = ২০৯০ − ২০০ + ১৮২ = ২১০৮। গড় = ১৯১.৬৩৬৩৬৩৬৩৬৩৬৩৬৩।","ভুল মোট থেকে ভুলভাবে যোগ হওয়া নম্বর বাদ দিয়ে প্রকৃত নম্বর যোগ করুন।");
 replaceQuestion('math_L29_Q4','সময় ও কাজ',"১৪ জন শ্রমিক দিনে ৬ ঘণ্টা করে ১৫ দিনে একটি কাজ করেন। ১৮ জন শ্রমিক দিনে ৭ ঘণ্টা কাজ করলে কত দিনে কাজটি শেষ হবে?",["১০","১১","৯","১২"],0,10,"দিন = (পুরোনো শ্রমিক × ঘণ্টা × দিন) ÷ (নতুন শ্রমিক × নতুন ঘণ্টা)","মোট কাজ = ১৪ × ৬ × ১৫ = ১২৬০ শ্রমিক-ঘণ্টা। প্রয়োজনীয় দিন = ১২৬০ ÷ (১৮ × ৭) = ১০ দিন।","মোট শ্রমিক-ঘণ্টা স্থির রেখে নতুন দৈনিক কাজের ক্ষমতা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L29_Q5','সময়-দূরত্ব',"একটি গাড়ি ৫১০ কিমি পথ ৪৫ কিমি/ঘণ্টা এবং পরের ৪০০ কিমি পথ ৮০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৫৯.৬১","৫১.৮১","৬৩.৫১","৫৫.৭১"],3,55.71,"গড় বেগ = মোট দূরত্ব ÷ মোট সময়","প্রথম অংশের সময় = ৫১০÷৪৫ = ১১.৩৩৩৩৩৩৩৩৩৩৩৩৩৩৪ ঘণ্টা; দ্বিতীয় অংশের সময় = ৪০০÷৮০ = ৫ ঘণ্টা। গড় বেগ = ৯১০÷১৬.৩৩ = ৫৫.৭১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L29_Q7','বয়স',"একজন পিতার বর্তমান বয়স ছেলের বয়সের ৫ গুণ। ৫ বছর পর তাঁদের বয়সের যোগফল ৯৪ বছর হবে। ৫ বছর পর ছেলের বয়স কত হবে?",["২০","১৮","১৯","২১"],2,19,"বর্তমান মোট বয়স = ভবিষ্যৎ মোট − দুজনের জন্য যোগ হওয়া বছর","বর্তমান মোট = ৯৪ − ১০ = ৮৪। ছেলের বর্তমান বয়স = ১৪; ৫ বছর পর = ১৯ বছর।","দুজনের বয়সে সমান বছর যোগ হয়; ভবিষ্যৎ মোট থেকে দ্বিগুণ সময় বাদ দিন।");
 replaceQuestion('math_L29_Q8','বীজগণিত',"একটি সংখ্যার ৫ গুণের সঙ্গে একই সংখ্যার ৫ গুণের দ্বিগুণ যোগ করলে ১৯৫ হয়। সংখ্যাটি কত?",["১৪","১৩","১২","১৫"],1,13,"ax + 2bx = c; x = c ÷ (a + 2b)","সমীকরণ: ৫x + ২×৫x = ১৯৫। তাই (১৫)x = ১৯৫; x = ১৩।","সমজাতীয় পদ একত্র করে সহগ দিয়ে ধ্রুবকটিকে ভাগ করুন।");
 replaceQuestion('math_L29_Q9','ল.সা.গু ও গ.সা.গু',"দুটি সতর্কসংকেত যথাক্রমে প্রতি ১৩ মিনিট ও ১৯ মিনিট পরপর বাজে। সকাল ৯টায় একসঙ্গে বাজলে আবার কত মিনিট পর একসঙ্গে বাজবে?",["২৪৭","২৬৪","২৩০","২৮১"],0,247,"পুনরায় একসঙ্গে ঘটার ব্যবধান = সময়গুলোর ল.সা.গু","১৩ ও ১৯-এর গ.সা.গু = ১। ল.সা.গু = (১৩×১৯)÷১ = ২৪৭ মিনিট।","একসঙ্গে ঘটনার পুনরাবৃত্তি নির্ণয়ে ল.সা.গু ব্যবহার করুন।");
 replaceQuestion('math_L30_Q2','জ্যামিতি ও ক্ষেত্রফল',"একটি আয়তাকার বাগানের দৈর্ঘ্য ২০ মিটার ও প্রস্থ ১৪ মিটার। উভয় মাত্রা ৭ মিটার করে বাড়ালে ক্ষেত্রফল কত বর্গমিটার বাড়বে?",["৩০৭","২৬৭","৩২৭","২৮৭"],3,287,"ক্ষেত্রফলের বৃদ্ধি = নতুন ক্ষেত্রফল − পুরোনো ক্ষেত্রফল","পুরোনো ক্ষেত্রফল = ২০×১৪ = ২৮০। নতুন ক্ষেত্রফল = ২৭×২১ = ৫৬৭। বৃদ্ধি = ২৮৭ বর্গমিটার।","দুই মাত্রা পরিবর্তনের পর নতুন ক্ষেত্রফল বের করে পুরোনোটি বাদ দিন।");
 replaceQuestion('math_L30_Q3','ধারা',"একটি সমান্তর ধারার প্রথম পদ ৮ এবং সাধারণ অন্তর ৩। প্রথম ১৫টি পদের যোগফল ৪৩৫ হলে ১৫তম পদ কত?",["৬২","৫৪","৫৮","৬৬"],2,58,"n-তম পদ = a + (n−1)d","n-তম পদ = ৮ + (১৫−১)×৩ = ৫৮।","পদের যোগফল নয়, নির্দিষ্ট পদের মানের জন্য a+(n−1)d ব্যবহার করুন।");
 replaceQuestion('math_L30_Q4','সরল সুদ',"একটি সঞ্চয়ে ২৪০০০ টাকা বার্ষিক ৫% সরল সুদে ২ বছর রাখা হলো। মেয়াদ শেষে আসলসহ মোট টাকা কত?",["২৮২৪৮","২৬৪০০","২৪৫৫২","৩০০৯৬"],1,26400,"মোট = আসল + (আসল × হার × সময় ÷ ১০০)","সুদ = ২৪০০০×৫×২÷১০০ = ২৪০০ টাকা। মোট = ২৪০০০+২৪০০ = ২৬৪০০ টাকা।","প্রথমে সরল সুদ বের করে আসলের সঙ্গে যোগ করুন।");
 replaceQuestion('math_L30_Q6','মিশ্রণ',"২৭% ও ৫২% ঘনত্বের দুটি দ্রবণ যথাক্রমে ৫ লিটার ও ৮ লিটার মেশানো হলো। মিশ্রণের ঘনত্ব কত শতাংশ?",["৪২.৩৮","৪৫.৩৫","৩৯.৪১","৪৮.৩২"],0,42.38,"মিশ্রণের ঘনত্ব = মোট দ্রবীভূত পদার্থ ÷ মোট আয়তন × ১০০","দ্রবীভূত পদার্থ = ১.৩৫ + ৪.১৬ = ৫.৫১ লিটার। মোট আয়তন = ১৩ লিটার। ঘনত্ব = ৪২.৩৮%。","প্রতিটি দ্রবণের প্রকৃত উপাদান আলাদা বের করে যোগ করুন।");
 replaceQuestion('math_L30_Q8','শতকরা',"একটি যন্ত্রের দাম ৩৯৩০ টাকা। প্রথমে দাম ১৪% বাড়ল, পরে বর্ধিত দামে ১৫% ছাড় দেওয়া হলো। চূড়ান্ত দাম কত?",["৪০৭৪.৭৪","৩৫৪১.৬","৪৩৪১.৩১","৩৮০৮.১৭"],3,3808.17,"চূড়ান্ত দাম = মূল দাম × (১ + বৃদ্ধির হার) × (১ − ছাড়ের হার)","বৃদ্ধির পর দাম = ৩৯৩০ × ১.১৪০০০০০০০০০০০০০১ = ৪৪৮০.২০০০০০০০০০০১ টাকা। এরপর ছাড়ের পর দাম = ৪৪৮০.২০০০০০০০০০০১ × ০.৮৫ = ৩৮০৮.১৭ টাকা।","পরপর শতকরা পরিবর্তনে হারগুলো সরাসরি যোগ-বিয়োগ নয়; ধারাবাহিক গুণ করুন।");

 replaceQuestion('math_L19_Q6','গড়',"একটি দলের ১১ জনের গড় নম্বর ৬০। একজনের ৫৮ নম্বর ভুল করে ৬৬ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["৬৩.৪২","৫৫.১২","৫৯.২৭","৬৭.৫৭"],2,59.27,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১১ × ৬০ = ৬৬০। সঠিক মোট = ৬৬০ − ৬৬ + ৫৮ = ৬৫২। সঠিক গড় = ৬৫২ ÷ ১১ = ৫৯.২৭।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L20_Q4','সময়-দূরত্ব',"একটি গাড়ি ১২০ কিমি পথ ৪৫ কিমি/ঘণ্টা এবং পরের ১৪০ কিমি পথ ৭০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৫৫.৭১","৫৯.৬১","৫১.৮১","৬৩.৫১"],0,55.71,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ১২০÷৪৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ১৪০÷৭০ ঘণ্টা। গড় বেগ = (১২০+১৪০) ÷ (১২০÷৪৫ + ১৪০÷৭০) = ৫৫.৭১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L22_Q5','গড়',"একটি দলের ৯ জনের গড় নম্বর ৮৬। একজনের ৭৮ নম্বর ভুল করে ৯৪ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["৯০.১২","৮৪.২২","৭৮.৩২","৯৬.০২"],1,84.22,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ৯ × ৮৬ = ৭৭৪। সঠিক মোট = ৭৭৪ − ৯৪ + ৭৮ = ৭৫৮। সঠিক গড় = ৭৫৮ ÷ ৯ = ৮৪.২২।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L22_Q7','সময়-দূরত্ব',"একটি গাড়ি ১৯৮ কিমি পথ ৬০ কিমি/ঘণ্টা এবং পরের ১৯২ কিমি পথ ৮০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৭৩.২১","৬৩.৬৩","৭৮.০০","৬৮.৪২"],3,68.42,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ১৯৮÷৬০ ঘণ্টা; দ্বিতীয় অংশের সময় = ১৯২÷৮০ ঘণ্টা। গড় বেগ = (১৯৮+১৯২) ÷ (১৯৮÷৬০ + ১৯২÷৮০) = ৬৮.৪২ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L24_Q2','গড়',"একটি দলের ১২ জনের গড় নম্বর ১১২। একজনের ১০৬ নম্বর ভুল করে ১২২ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১১০.৬৭","১১৮.৪২","১০২.৯২","১২৬.১৭"],0,110.67,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১২ × ১১২ = ১৩৪৪। সঠিক মোট = ১৩৪৪ − ১২২ + ১০৬ = ১৩২৮। সঠিক গড় = ১৩২৮ ÷ ১২ = ১১০.৬৭।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L24_Q4','সময়-দূরত্ব',"একটি গাড়ি ২৭৬ কিমি পথ ৫০ কিমি/ঘণ্টা এবং পরের ২৪৪ কিমি পথ ৯০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬৭.৫৯","৫৮.৭৫","৬৩.১৭","৭২.০১"],2,63.17,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ২৭৬÷৫০ ঘণ্টা; দ্বিতীয় অংশের সময় = ২৪৪÷৯০ ঘণ্টা। গড় বেগ = (২৭৬+২৪৪) ÷ (২৭৬÷৫০ + ২৪৪÷৯০) = ৬৩.১৭ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L25_Q7','গড়',"একটি দলের ১০ জনের গড় নম্বর ১৩৮। একজনের ১৩৪ নম্বর ভুল করে ১৪৪ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১৪৬.৫৯","১২৭.৪১","১৫৬.১৮","১৩৭.০০"],3,137,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১০ × ১৩৮ = ১৩৮০। সঠিক মোট = ১৩৮০ − ১৪৪ + ১৩৪ = ১৩৭০। সঠিক গড় = ১৩৭০ ÷ ১০ = ১৩৭।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L25_Q9','সময়-দূরত্ব',"একটি গাড়ি ৩৫৪ কিমি পথ ৬৫ কিমি/ঘণ্টা এবং পরের ২৯৬ কিমি পথ ৬০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬৭.০০","৬২.৬২","৫৮.২৪","৭১.৩৮"],1,62.62,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ৩৫৪÷৬৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ২৯৬÷৬০ ঘণ্টা। গড় বেগ = (৩৫৪+২৯৬) ÷ (৩৫৪÷৬৫ + ২৯৬÷৬০) = ৬২.৬২ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L27_Q5','গড়',"একটি দলের ৮ জনের গড় নম্বর ১৬৪। একজনের ১৬২ নম্বর ভুল করে ১৭২ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["১৭৪.১৪","১৫১.৩৬","১৬২.৭৫","১৮৫.৫৩"],2,162.75,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ৮ × ১৬৪ = ১৩১২। সঠিক মোট = ১৩১২ − ১৭২ + ১৬২ = ১৩০২। সঠিক গড় = ১৩০২ ÷ ৮ = ১৬২.৭৫।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L27_Q7','সময়-দূরত্ব',"একটি গাড়ি ৪৩২ কিমি পথ ৫৫ কিমি/ঘণ্টা এবং পরের ৩৪৮ কিমি পথ ৭০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৬০.৮১","৬৫.০৭","৫৬.৫৫","৬৯.৩৩"],0,60.81,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ৪৩২÷৫৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ৩৪৮÷৭০ ঘণ্টা। গড় বেগ = (৪৩২+৩৪৮) ÷ (৪৩২÷৫৫ + ৩৪৮÷৭০) = ৬০.৮১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");
 replaceQuestion('math_L29_Q3','গড়',"একটি দলের ১১ জনের গড় নম্বর ১৯০। একজনের ১৮২ নম্বর ভুল করে ২০০ লেখা হয়েছিল। সংশোধনের পর সঠিক গড় কত?",["২০১.৫৫","১৮৮.৩৬","১৭৫.১৭","২১৪.৭৪"],1,188.36,"সঠিক গড় = (ভুল মোট − ভুলভাবে লেখা নম্বর + প্রকৃত নম্বর) ÷ সদস্যসংখ্যা","ভুল মোট = ১১ × ১৯০ = ২০৯০। সঠিক মোট = ২০৯০ − ২০০ + ১৮২ = ২০৭২। সঠিক গড় = ২০৭২ ÷ ১১ = ১৮৮.৩৬।","ভুল মোট থেকে ভুলভাবে বেশি/কম লেখা নম্বরের প্রভাব সংশোধন করে সদস্যসংখ্যা দিয়ে ভাগ করুন।");
 replaceQuestion('math_L29_Q5','সময়-দূরত্ব',"একটি গাড়ি ৫১০ কিমি পথ ৪৫ কিমি/ঘণ্টা এবং পরের ৪০০ কিমি পথ ৮০ কিমি/ঘণ্টা বেগে চলে। পুরো যাত্রার গড় বেগ কত?",["৫৯.৬১","৫১.৮১","৬৩.৫১","৫৫.৭১"],3,55.71,"গড় বেগ = মোট দূরত্ব ÷ (প্রথম অংশের সময় + দ্বিতীয় অংশের সময়)","প্রথম অংশের সময় = ৫১০÷৪৫ ঘণ্টা; দ্বিতীয় অংশের সময় = ৪০০÷৮০ ঘণ্টা। গড় বেগ = (৫১০+৪০০) ÷ (৫১০÷৪৫ + ৪০০÷৮০) = ৫৫.৭১ কিমি/ঘণ্টা।","প্রতিটি অংশের সময় আলাদা বের করে মোট দূরত্বকে মোট সময়ে ভাগ করুন।");

 window.ML_MATH_LEVELS=Array.from({length:30},(_,i)=>({level:i+1,title:'লেভেল '+bn(i+1),band:bands(i+1),questions:bank.filter(q=>q.level===i+1)}));
 window.ML_MATH_BANK=bank;
 function openMath(){const panel=document.getElementById('featurePanel'),title=document.getElementById('featureTitle'),body=document.getElementById('featureBody');if(!panel||!body)return;title.textContent='গণিত · ৩০ স্তরের প্রস্তুতি';
 let level=1,pos=0,score=0,done=false,levelSaved=false;
 const getNextLevel=()=>{const p=readProgress();for(let n=1;n<=30;n++)if(!p[n]?.completedAt)return n;return 31};
 const drawHome=()=>{const p=readProgress(),completed=Object.keys(p).filter(k=>p[k]?.completedAt&&Number(k)>=1&&Number(k)<=30).length,nextLevel=getNextLevel(),shownLevel=nextLevel<=30?nextLevel:30,pct=Math.round(completed/30*100);level=shownLevel;body.innerHTML='<div class="notice"><b>গণিত প্রস্তুতি · ৩০টি ধারাবাহিক স্তর</b><br>মোট ৩০০টি প্রশ্ন। প্রতি স্তরে ১০টি প্রশ্ন। একটি স্তর শেষ করলেই পরের স্তর স্বয়ংক্রিয়ভাবে চালু হবে। সঠিক উত্তরে +১, ভুল উত্তরে −০.২৫।</div><div class="card"><div class="row"><b>আপনার অগ্রগতি</b><b>'+bn(completed)+'/৩০</b></div><div class="progress"><div class="bar" style="width:'+pct+'%"></div></div><h3>'+(nextLevel<=30?'এখনকার স্তর: '+bn(nextLevel):'সব ৩০টি স্তর সম্পন্ন!')+'</h3><p class="muted">'+(nextLevel<=30?'পরের স্তরগুলো তালিকা থেকে বেছে নিতে হবে না—একটির পর একটি খুলবে।':'আপনি সম্পূর্ণ গণিত প্রস্তুতি শেষ করেছেন। চাইলে শেষ স্তরটি আবার অনুশীলন করতে পারেন।')+'</p><button id="mathStart" class="start-3d">'+(nextLevel<=30?'▶ প্রস্তুতি চালিয়ে যান':'শেষ স্তর আবার অনুশীলন')+'</button></div><button id="mathReturn" class="secondary">চাকরির প্রস্তুতি কেন্দ্রে ফিরুন</button>';document.getElementById('mathStart').textContent=nextLevel<=30?'▶ প্রস্তুতি চালিয়ে যান':'শেষ স্তর আবার অনুশীলন';document.getElementById('mathStart').onclick=()=>nextLevel<=30?launchLevel(nextLevel):start(30);document.getElementById('mathReturn').onclick=()=>typeof window.openJobPrep==='function'?window.openJobPrep():window.show('home')};
 const start=l=>{level=l;pos=0;score=0;done=false;levelSaved=false;drawQuestion()};
 const launchLevel=l=>{if(l>30)return;const showInterstitial=window.ML_SHOW_INTERSTITIAL_AD;if(l>1&&(l-1)%2===0&&typeof showInterstitial==='function'){showInterstitial(()=>start(l));}else start(l)};
 const drawQuestion=()=>{const q=window.ML_MATH_LEVELS[level-1].questions[pos];if(!q){if(!levelSaved){saveProgress(level,score);levelSaved=true;}const next=level+1;body.innerHTML='<div class="card"><h3>লেভেল '+bn(level)+' সম্পন্ন! 🎉</h3><p>এই লেভেলে অর্জিত স্কোর: '+bn(score.toFixed(2))+' / ১০</p><div class="notice">'+(next<=30?'চমৎকার! পরবর্তী লেভেল '+bn(next)+' এখন প্রস্তুত। লেভেল বাটন খুঁজতে হবে না—নিচের বোতাম চাপলেই পরের ধাপ শুরু হবে।':'অভিনন্দন! আপনি গণিতের সব ৩০টি লেভেল সম্পন্ন করেছেন।')+'</div><button id="mathNextLevel" class="start-3d">'+(next<=30?'পরবর্তী লেভেল শুরু করুন':'সব লেভেল সম্পন্ন · আবার শুরু')+'</button><button id="mathLevels" class="secondary">চাকরির প্রস্তুতি কেন্দ্রে ফিরুন</button></div>';document.getElementById('mathNextLevel').textContent=next<=30?'পরবর্তী লেভেল শুরু করুন':'সব লেভেল সম্পন্ন · আবার শুরু';document.getElementById('mathNextLevel').onclick=()=>next<=30?launchLevel(next):drawHome();document.getElementById('mathLevels').onclick=()=>typeof window.openJobPrep==='function'?window.openJobPrep():window.show('home');return}
 body.innerHTML='<div class="row"><b>লেভেল '+bn(level)+' · '+q.topic+'</b><small>প্রশ্ন '+bn(pos+1)+'/১০</small></div><div class="question">'+q.q+'</div><div class="answers">'+q.o.map((v,i)=>'<button class="answer" data-i="'+i+'">'+['ক','খ','গ','ঘ'][i]+'. '+v+'</button>').join('')+'</div><div id="mathFeedback" class="notice hidden"></div><div class="row"><b>স্কোর: '+bn(score.toFixed(2))+'</b><button id="mathContinue" class="hidden">পরের প্রশ্ন</button></div>';
 body.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(done)return;done=true;const ok=+b.dataset.i===q.a;score=Number((score+(ok?1:-.25)).toFixed(2));body.querySelectorAll('[data-i]').forEach((x,i)=>{x.disabled=true;if(i===q.a)x.style.border='2px solid #67e0bd'});const f=document.getElementById('mathFeedback');f.classList.remove('hidden');f.innerHTML='<b>'+(ok?'সঠিক উত্তর! +১':'ভুল উত্তর। −০.২৫ · সঠিক উত্তর: '+q.o[q.a])+'</b><br><b>সূত্র:</b> '+q.formula+'<br><b>সমাধান:</b> '+q.e+'<br><b>দ্রুত কৌশল:</b> '+q.shortcut;document.getElementById('mathContinue').classList.remove('hidden')});document.getElementById('mathContinue').onclick=()=>{pos++;done=false;drawQuestion()};};
 drawHome();window.show('featurePanel');}
 window.openMathLevelHome=openMath;
 // গণিতের প্রবেশপথ চাকরির প্রস্তুতি ড্যাশবোর্ডের বিষয় তালিকায় রয়েছে।
})();